1	const UUID_PATTERN =
2	  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
3	
4	export function buildBillingCreditApplicationUpdate(input: {
5	  localInvoiceId: string;
6	  stripeInvoiceId: string;
7	}) {
8	  if (!UUID_PATTERN.test(input.localInvoiceId)) {
9	    throw new Error('Billing credit local invoice ID must be a UUID');
10	  }
11	  if (!input.stripeInvoiceId.startsWith('in_')) {
12	    throw new Error(
13	      'Billing credit Stripe invoice ID must be a Stripe invoice ID',
14	    );
15	  }
16	
17	  return {
18	    appliedToInvoiceId: input.localInvoiceId,
19	    appliedToStripeInvoiceId: input.stripeInvoiceId,
20	  };
21	}
