1	import { AccountingOwnerScopeError } from './owner-scope';
2	
3	export const ACCOUNTING_SYNC_MODES = [
4	  'HAP_PRIMARY',
5	  'QUICKBOOKS_PRIMARY',
6	  'BIDIRECTIONAL_MANAGED',
7	  'REPORTING_ONLY',
8	] as const;
9	
10	export const PAYROLL_MODES = [
11	  'NO_PAYROLL_SYNC',
12	  'PAYROLL_SUMMARY_EXPORT',
13	  'JOURNAL_ENTRY_SYNC',
14	  'PAYROLL_DATA_IMPORT',
15	  'PAYROLL_API_SYNC',
16	  'THIRD_PARTY_PAYROLL_INTEGRATION',
17	] as const;
18	
19	export type AccountingSyncMode = (typeof ACCOUNTING_SYNC_MODES)[number];
20	export type AccountingSyncOperation = 'create' | 'update' | 'delete' | 'read';
21	export type PayrollMode = (typeof PAYROLL_MODES)[number];
22	
23	export interface AccountingSyncRulePolicy {
24	  syncDirection?: string | null;
25	  sourceOfTruth?: string | null;
26	  conflictPolicy?: string | null;
27	  createEnabled?: boolean | null;
28	  updateEnabled?: boolean | null;
29	  deleteEnabled?: boolean | null;
30	}
31	
32	export function isAccountingSyncMode(
33	  value: unknown,
34	): value is AccountingSyncMode {
35	  return ACCOUNTING_SYNC_MODES.includes(value as AccountingSyncMode);
36	}
37	
38	export function isPayrollMode(value: unknown): value is PayrollMode {
39	  return PAYROLL_MODES.includes(value as PayrollMode);
40	}
41	
42	function isProviderWriteOperation(operation: AccountingSyncOperation): boolean {
43	  return (
44	    operation === 'create' || operation === 'update' || operation === 'delete'
45	  );
46	}
47	
48	export function canWriteToQuickBooks(input: {
49	  syncMode: AccountingSyncMode;
50	  operation: AccountingSyncOperation;
51	  rule?: AccountingSyncRulePolicy | null;
52	}): boolean {
53	  if (!isProviderWriteOperation(input.operation)) return true;
54	  if (input.syncMode === 'REPORTING_ONLY') return false;
55	  if (input.syncMode === 'QUICKBOOKS_PRIMARY') return false;
56	
57	  const rule = input.rule;
58	  if (!rule) return input.syncMode === 'HAP_PRIMARY';
59	  if (rule.syncDirection === 'READ_ONLY') return false;
60	  if (rule.syncDirection === 'PROVIDER_TO_HAP') return false;
61	
62	  if (input.operation === 'create') return rule.createEnabled ?? false;
63	  if (input.operation === 'update') return rule.updateEnabled ?? false;
64	  return rule.deleteEnabled ?? false;
65	}
66	
67	export function assertQuickBooksWriteAllowed(input: {
68	  syncMode: AccountingSyncMode;
69	  operation: AccountingSyncOperation;
70	  objectType: string;
71	  rule?: AccountingSyncRulePolicy | null;
72	}): void {
73	  if (canWriteToQuickBooks(input)) return;
74	  throw new AccountingOwnerScopeError(
75	    `QuickBooks ${input.operation} is not allowed for ${input.objectType} in ${input.syncMode} mode`,
76	  );
77	}
78	
79	export function assertPayrollModeAllowed(input: {
80	  payrollMode: PayrollMode;
81	  payrollApiSyncEnabled?: boolean;
82	}): void {
83	  if (
84	    input.payrollMode === 'PAYROLL_API_SYNC' &&
85	    input.payrollApiSyncEnabled !== true
86	  ) {
87	    throw new AccountingOwnerScopeError(
88	      'PAYROLL_API_SYNC is disabled until QuickBooks Payroll API capability is explicitly enabled',
89	    );
90	  }
91	}
