1	export const ACCOUNTING_OWNER_TYPES = [
2	  'HILO_PLATFORM',
3	  'FLIGHT_SCHOOL',
4	] as const;
5	
6	export const ACCOUNTING_PROVIDERS = ['STRIPE', 'QUICKBOOKS'] as const;
7	
8	export type AccountingOwnerType = (typeof ACCOUNTING_OWNER_TYPES)[number];
9	export type AccountingProvider = (typeof ACCOUNTING_PROVIDERS)[number];
10	
11	export interface AccountingOwnerScope {
12	  ownerType: AccountingOwnerType;
13	  ownerId: string;
14	}
15	
16	export interface ProviderAccountScope extends AccountingOwnerScope {
17	  provider: AccountingProvider;
18	  providerAccountId: string;
19	}
20	
21	export interface ProviderObjectLookupScope extends ProviderAccountScope {
22	  externalObjectType: string;
23	  externalObjectId: string;
24	}
25	
26	export interface IntegrationObjectMappingKey extends ProviderObjectLookupScope {
27	  key: string;
28	}
29	
30	export interface ProviderIdempotencyScope extends ProviderAccountScope {
31	  operation: string;
32	  objectType: string;
33	  objectId: string;
34	  idempotencyKey: string;
35	}
36	
37	export class AccountingOwnerScopeError extends Error {
38	  constructor(message: string) {
39	    super(message);
40	    this.name = 'AccountingOwnerScopeError';
41	  }
42	}
43	
44	function isOwnerType(value: string): value is AccountingOwnerType {
45	  return ACCOUNTING_OWNER_TYPES.includes(value as AccountingOwnerType);
46	}
47	
48	function isProvider(value: string): value is AccountingProvider {
49	  return ACCOUNTING_PROVIDERS.includes(value as AccountingProvider);
50	}
51	
52	function assertNonBlank(value: unknown, field: string): string {
53	  if (typeof value !== 'string' || value.trim().length === 0) {
54	    throw new AccountingOwnerScopeError(`${field} is required`);
55	  }
56	  return value.trim();
57	}
58	
59	export function normalizeOwnerScope(input: {
60	  ownerType?: string | null;
61	  ownerId?: string | null;
62	}): AccountingOwnerScope {
63	  const ownerTypeRaw = assertNonBlank(input.ownerType, 'ownerType');
64	  if (!isOwnerType(ownerTypeRaw)) {
65	    throw new AccountingOwnerScopeError(
66	      `Unsupported ownerType: ${ownerTypeRaw}`,
67	    );
68	  }
69	
70	  const ownerId = assertNonBlank(input.ownerId, 'ownerId');
71	  return { ownerType: ownerTypeRaw, ownerId };
72	}
73	
74	export function assertHiloPlatformOwner(
75	  input: AccountingOwnerScope,
76	): AccountingOwnerScope {
77	  const owner = normalizeOwnerScope(input);
78	  if (owner.ownerType !== 'HILO_PLATFORM') {
79	    throw new AccountingOwnerScopeError(
80	      'Hilo platform accounting requires ownerType HILO_PLATFORM',
81	    );
82	  }
83	  return owner;
84	}
85	
86	export function assertFlightSchoolOwner(
87	  input: AccountingOwnerScope,
88	): AccountingOwnerScope {
89	  const owner = normalizeOwnerScope(input);
90	  if (owner.ownerType !== 'FLIGHT_SCHOOL') {
91	    throw new AccountingOwnerScopeError(
92	      'Flight school accounting requires ownerType FLIGHT_SCHOOL',
93	    );
94	  }
95	  return owner;
96	}
97	
98	export function normalizeProviderAccountScope(input: {
99	  ownerType?: string | null;
100	  ownerId?: string | null;
101	  provider?: string | null;
102	  providerAccountId?: string | null;
103	}): ProviderAccountScope {
104	  const owner = normalizeOwnerScope(input);
105	  const providerRaw = assertNonBlank(input.provider, 'provider');
106	  if (!isProvider(providerRaw)) {
107	    throw new AccountingOwnerScopeError(`Unsupported provider: ${providerRaw}`);
108	  }
109	
110	  return {
111	    ...owner,
112	    provider: providerRaw,
113	    providerAccountId: assertNonBlank(
114	      input.providerAccountId,
115	      'providerAccountId',
116	    ),
117	  };
118	}
119	
120	export function normalizeProviderObjectLookupScope(input: {
121	  ownerType?: string | null;
122	  ownerId?: string | null;
123	  provider?: string | null;
124	  providerAccountId?: string | null;
125	  externalObjectType?: string | null;
126	  externalObjectId?: string | null;
127	}): ProviderObjectLookupScope {
128	  const account = normalizeProviderAccountScope(input);
129	  return {
130	    ...account,
131	    externalObjectType: assertNonBlank(
132	      input.externalObjectType,
133	      'externalObjectType',
134	    ),
135	    externalObjectId: assertNonBlank(
136	      input.externalObjectId,
137	      'externalObjectId',
138	    ),
139	  };
140	}
141	
142	export function buildIntegrationObjectMappingKey(input: {
143	  ownerType?: string | null;
144	  ownerId?: string | null;
145	  provider?: string | null;
146	  providerAccountId?: string | null;
147	  externalObjectType?: string | null;
148	  externalObjectId?: string | null;
149	}): IntegrationObjectMappingKey {
150	  const scope = normalizeProviderObjectLookupScope(input);
151	  return {
152	    ...scope,
153	    key: [
154	      scope.ownerType,
155	      scope.ownerId,
156	      scope.provider,
157	      scope.providerAccountId,
158	      scope.externalObjectType,
159	      scope.externalObjectId,
160	    ].join('|'),
161	  };
162	}
163	
164	export function buildProviderIdempotencyKey(input: {
165	  ownerType?: string | null;
166	  ownerId?: string | null;
167	  provider?: string | null;
168	  providerAccountId?: string | null;
169	  operation?: string | null;
170	  objectType?: string | null;
171	  objectId?: string | null;
172	  phase?: string | null;
173	}): ProviderIdempotencyScope {
174	  const account = normalizeProviderAccountScope(input);
175	  const operation = assertNonBlank(input.operation, 'operation');
176	  const objectType = assertNonBlank(input.objectType, 'objectType');
177	  const objectId = assertNonBlank(input.objectId, 'objectId');
178	  const phase =
179	    input.phase === undefined || input.phase === null
180	      ? null
181	      : assertNonBlank(input.phase, 'phase');
182	
183	  return {
184	    ...account,
185	    operation,
186	    objectType,
187	    objectId,
188	    idempotencyKey: [
189	      account.ownerType,
190	      account.ownerId,
191	      account.provider,
192	      account.providerAccountId,
193	      operation,
194	      objectType,
195	      objectId,
196	      phase,
197	    ]
198	      .filter(Boolean)
199	      .join('|'),
200	  };
201	}
202	
203	export function assertLegacyProviderPathBlocked(input: {
204	  path: string;
205	  replacement: string;
206	  enabled?: boolean;
207	}): void {
208	  if (input.enabled) return;
209	  throw new AccountingOwnerScopeError(
210	    `${assertNonBlank(input.path, 'path')} is blocked because it is not owner-scoped; use ${assertNonBlank(
211	      input.replacement,
212	      'replacement',
213	    )}`,
214	  );
215	}
216	
217	export function assertQuickBooksConnectionForOwner(
218	  connection: {
219	    ownerType?: string | null;
220	    ownerId?: string | null;
221	    provider?: string | null;
222	    providerAccountId?: string | null;
223	  },
224	  expectedOwner: AccountingOwnerScope,
225	): ProviderAccountScope {
226	  const scopedConnection = normalizeProviderAccountScope(connection);
227	  const owner = normalizeOwnerScope(expectedOwner);
228	
229	  if (scopedConnection.provider !== 'QUICKBOOKS') {
230	    throw new AccountingOwnerScopeError(
231	      `Expected QUICKBOOKS connection, received ${scopedConnection.provider}`,
232	    );
233	  }
234	
235	  if (
236	    scopedConnection.ownerType !== owner.ownerType ||
237	    scopedConnection.ownerId !== owner.ownerId
238	  ) {
239	    throw new AccountingOwnerScopeError(
240	      `QuickBooks connection owner mismatch: connection=${scopedConnection.ownerType}/${scopedConnection.ownerId} expected=${owner.ownerType}/${owner.ownerId}`,
241	    );
242	  }
243	
244	  return scopedConnection;
245	}
246	
247	export function assertSyncJobOwnerContext(input: {
248	  ownerType?: string | null;
249	  ownerId?: string | null;
250	  provider?: string | null;
251	  providerAccountId?: string | null;
252	}): ProviderAccountScope {
253	  return normalizeProviderAccountScope(input);
254	}
