256	export function buildAccountingAuditLog(input: {
257	  ownerType?: string | null;
258	  ownerId?: string | null;
259	  provider?: string | null;
260	  action: string;
261	  objectType?: string | null;
262	  internalObjectId?: string | null;
263	  externalObjectId?: string | null;
264	  actorUserId?: string | null;
265	  metadata?: Record<string, unknown>;
266	}) {
267	  const owner = normalizeOwnerScope(input);
268	  const provider =
269	    input.provider === undefined || input.provider === null
270	      ? null
271	      : normalizeProviderAccountScope({
272	          ...owner,
273	          provider: input.provider,
274	          providerAccountId: 'audit-only',
275	        }).provider;
276	
277	  return {
278	    ...owner,
279	    provider,
280	    action: assertNonBlank(input.action, 'action'),
281	    objectType: input.objectType ?? null,
282	    internalObjectId: input.internalObjectId ?? null,
283	    externalObjectId: input.externalObjectId ?? null,
284	    actorUserId: input.actorUserId ?? null,
285	    metadata: input.metadata ?? {},
286	  };
287	}
