1	import { db } from '@/lib/db';
2	import * as schema from '@/lib/schema';
3	import { asc } from 'drizzle-orm';
4	
5	export interface ProviderConnectionFirewallRow {
6	  id?: string;
7	  ownerType: 'HILO_PLATFORM' | 'FLIGHT_SCHOOL';
8	  ownerId: string;
9	  provider: 'STRIPE' | 'QUICKBOOKS';
10	  providerAccountId: string;
11	  status?: string | null;
12	}
13	
14	export interface FirewallCollision {
15	  provider: 'STRIPE' | 'QUICKBOOKS';
16	  providerAccountId: string;
17	  owners: Array<{
18	    ownerType: 'HILO_PLATFORM' | 'FLIGHT_SCHOOL';
19	    ownerId: string;
20	    connectionId?: string;
21	  }>;
22	}
23	
24	export function summarizeAccountingIntegrationFirewall(
25	  connections: ProviderConnectionFirewallRow[],
26	) {
27	  const byProviderAccount = new Map<string, ProviderConnectionFirewallRow[]>();
28	  for (const connection of connections) {
29	    const key = `${connection.provider}|${connection.providerAccountId}`;
30	    byProviderAccount.set(key, [
31	      ...(byProviderAccount.get(key) ?? []),
32	      connection,
33	    ]);
34	  }
35	
36	  const collisions: FirewallCollision[] = [];
37	  for (const rows of byProviderAccount.values()) {
38	    const ownerKeys = new Set(
39	      rows.map((row) => `${row.ownerType}|${row.ownerId}`),
40	    );
41	    const ownerTypes = new Set(rows.map((row) => row.ownerType));
42	    if (ownerKeys.size <= 1 && ownerTypes.size <= 1) continue;
43	
44	    collisions.push({
45	      provider: rows[0].provider,
46	      providerAccountId: rows[0].providerAccountId,
47	      owners: rows.map((row) => ({
48	        ownerType: row.ownerType,
49	        ownerId: row.ownerId,
50	        connectionId: row.id,
51	      })),
52	    });
53	  }
54	
55	  const hiloConnections = connections.filter(
56	    (connection) => connection.ownerType === 'HILO_PLATFORM',
57	  );
58	  const flightSchoolConnections = connections.filter(
59	    (connection) => connection.ownerType === 'FLIGHT_SCHOOL',
60	  );
61	
62	  return {
63	    ready: collisions.length === 0,
64	    checks: [
65	      {
66	        key: 'hilo_connections_owner_scoped',
67	        status: hiloConnections.every(
68	          (connection) => connection.ownerType === 'HILO_PLATFORM',
69	        )
70	          ? 'PASS'
71	          : 'FAIL',
72	        message: 'Hilo provider connections are scoped to HILO_PLATFORM.',
73	      },
74	      {
75	        key: 'flight_school_connections_owner_scoped',
76	        status: flightSchoolConnections.every(
77	          (connection) => connection.ownerType === 'FLIGHT_SCHOOL',
78	        )
79	          ? 'PASS'
80	          : 'FAIL',
81	        message:
82	          'Flight school provider connections are scoped to FLIGHT_SCHOOL.',
83	      },
84	      {
85	        key: 'provider_account_not_shared_across_owners',
86	        status: collisions.length === 0 ? 'PASS' : 'FAIL',
87	        message:
88	          collisions.length === 0
89	            ? 'No provider account IDs are shared across owners.'
90	            : 'Provider account IDs are shared across owner boundaries.',
91	      },
92	    ],
93	    summary: {
94	      hiloConnectionCount: hiloConnections.length,
95	      flightSchoolConnectionCount: flightSchoolConnections.length,
96	      collisionCount: collisions.length,
97	    },
98	    collisions,
99	  };
100	}
101	
102	export async function getAccountingIntegrationFirewallStatus() {
103	  const rows = await db
104	    .select({
105	      id: schema.accountingProviderConnections.id,
106	      ownerType: schema.accountingProviderConnections.ownerType,
107	      ownerId: schema.accountingProviderConnections.ownerId,
108	      provider: schema.accountingProviderConnections.provider,
109	      providerAccountId: schema.accountingProviderConnections.providerAccountId,
110	      status: schema.accountingProviderConnections.status,
111	    })
112	    .from(schema.accountingProviderConnections)
113	    .orderBy(
114	      asc(schema.accountingProviderConnections.provider),
115	      asc(schema.accountingProviderConnections.providerAccountId),
116	    );
117	
118	  return summarizeAccountingIntegrationFirewall(rows);
119	}
