62	export function isHiloQuickBooksAccountMappingKey(
63	  value: string,
64	): value is HiloQuickBooksAccountMappingKey {
65	  return HILO_QUICKBOOKS_ACCOUNT_MAPPING_DEFINITIONS.some(
66	    (definition) => definition.mappingKey === value,
67	  );
68	}
