76	export function evaluateRequiredHiloQuickBooksAccountMappings(
77	  mappings: AccountMappingReadinessRecord[] = [],
78	) {
79	  const rowsByKey = new Map(mappings.map((row) => [row.mappingKey, row]));
80	  const providerAccountId = mappings.find(
81	    (row) => row.providerAccountId,
82	  )?.providerAccountId;
83	  const missingKeys = HILO_QUICKBOOKS_ACCOUNT_MAPPING_DEFINITIONS.filter(
84	    (definition) => {
85	      if (!definition.required) return false;
86	      const row = rowsByKey.get(definition.mappingKey);
87	      return (
88	        !row ||
89	        row.status !== 'ACTIVE' ||
90	        !row.externalAccountId ||
91	        !row.providerAccountId ||
92	        row.providerAccountId !== providerAccountId
93	      );
94	    },
95	  ).map((definition) => definition.mappingKey);
96	
97	  return {
98	    complete: missingKeys.length === 0,
99	    missingKeys,
100	    providerAccountId: providerAccountId ?? null,
