188	export async function upsertHiloQuickBooksAccountMapping(input: {
189	  ownerId: string;
190	  providerAccountId: string;
191	  mappingKey: string;
192	  externalAccountId: string;
193	  externalAccountName?: string | null;
194	  accountType?: string | null;
195	  actorUserId?: string | null;
196	}) {
197	  assertHiloPlatformOwner({
198	    ownerType: 'HILO_PLATFORM',
199	    ownerId: input.ownerId,
200	  });
201	
202	  const providerAccountId = input.providerAccountId.trim();
203	  const externalAccountId = input.externalAccountId.trim();
204	  if (!providerAccountId) {
205	    throw new Error('providerAccountId is required for account mappings');
206	  }
207	  if (!externalAccountId) {
208	    throw new Error('externalAccountId is required for account mappings');
209	  }
210	
211	  const definition = getHiloQuickBooksAccountMappingDefinition(
212	    input.mappingKey,
213	  );
214	  if (!definition) {
215	    throw new Error(
216	      `Unsupported Hilo QuickBooks mapping key: ${input.mappingKey}`,
217	    );
218	  }
219	
220	  const now = new Date();
221	  const values = {
222	    ownerType: 'HILO_PLATFORM' as const,
223	    ownerId: input.ownerId,
224	    provider: 'QUICKBOOKS' as const,
225	    providerAccountId,
226	    mappingKey: definition.mappingKey,
227	    displayName: definition.displayName,
228	    externalAccountId,
229	    externalAccountName: input.externalAccountName?.trim() || null,
230	    accountType: input.accountType?.trim() || definition.accountType,
231	    required: definition.required,
232	    status: 'ACTIVE',
233	    updatedByUserId: input.actorUserId ?? null,
234	    updatedAt: now,
235	  };
236	
237	  const [mapping] = await db
238	    .insert(schema.accountingAccountMappings)
239	    .values({
240	      ...values,
241	      createdByUserId: input.actorUserId ?? null,
242	      createdAt: now,
243	    })
244	    .onConflictDoUpdate({
245	      target: [
246	        schema.accountingAccountMappings.ownerType,
247	        schema.accountingAccountMappings.ownerId,
248	        schema.accountingAccountMappings.provider,
249	        schema.accountingAccountMappings.providerAccountId,
250	        schema.accountingAccountMappings.mappingKey,
251	      ],
252	      set: values,
253	    })
254	    .returning();
255	
256	  return mapping;
257	}
