96	export function evaluateAccountingProductionReadiness(
97	  input: AccountingProductionReadinessInput = {},
98	) {
99	  const env = input.env ?? process.env;
100	  const requireStripe = input.requireStripe ?? true;
101	  const quickBooksWritesEnabled =
102	    envEnabled(env, 'ENABLE_QUICKBOOKS_SANDBOX_WRITES') ||
103	    envEnabled(env, 'ENABLE_QUICKBOOKS_PRODUCTION_WRITES');
104	  const requireQuickBooksWrites =
105	    input.requireQuickBooksWrites ?? quickBooksWritesEnabled;
106	  const requireFinanceSignoff =
107	    input.requireFinanceSignoff ?? requireQuickBooksWrites;
108	  const requireAccountMappings =
109	    input.requireAccountMappings ?? requireFinanceSignoff;
110	  const checks: AccountingReadinessCheck[] = [];
111	
112	  if (requireStripe) {
113	    checks.push(
114	      configCheck(
115	        env,
116	        'STRIPE_WEBHOOK_SECRET',
117	        'Stripe webhook verification secret is required.',
118	      ),
119	      configCheck(
120	        env,
121	        'HILO_STRIPE_ACCOUNT_ID',
122	        'Hilo platform Stripe provider account ID is required.',
123	      ),
124	      configCheck(
125	        env,
126	        'STRIPE_PAYMENT_FEE_NONTAXABLE_TAX_CODE',
127	        'Non-taxable Stripe tax code is required for processing-fee lines.',
128	      ),
129	    );
130	  }
131	
132	  checks.push({
133	    key: 'config.ENABLE_QUICKBOOKS_SANDBOX_WRITES',
134	    status: envEnabled(env, 'ENABLE_QUICKBOOKS_SANDBOX_WRITES')
135	      ? 'PASS'
136	      : 'PASS',
137	    severity: 'WARNING',
138	    message: envEnabled(env, 'ENABLE_QUICKBOOKS_SANDBOX_WRITES')
139	      ? 'QuickBooks sandbox writes are enabled and require finance signoff.'
140	      : 'QuickBooks sandbox writes are disabled.',
141	  });
142	
143	  checks.push({
144	    key: 'config.ENABLE_QUICKBOOKS_PRODUCTION_WRITES',
145	    status: envEnabled(env, 'ENABLE_QUICKBOOKS_PRODUCTION_WRITES')
146	      ? 'FAIL'
147	      : 'PASS',
148	    severity: 'BLOCKER',
149	    message: envEnabled(env, 'ENABLE_QUICKBOOKS_PRODUCTION_WRITES')
150	      ? 'QuickBooks production writes require a separately approved adapter rollout.'
151	      : 'QuickBooks production writes are disabled.',
152	  });
153	
154	  checks.push({
155	    key: 'config.QB_PAYROLL_API_SYNC_ENABLED',
156	    status:
157	      envEnabled(env, 'QB_PAYROLL_API_SYNC_ENABLED') &&
158	      !envEnabled(env, 'QB_PAYROLL_API_CAPABILITY_CONFIRMED')
159	        ? 'FAIL'
160	        : 'PASS',
161	    severity: 'BLOCKER',
162	    message:
163	      envEnabled(env, 'QB_PAYROLL_API_SYNC_ENABLED') &&
164	      !envEnabled(env, 'QB_PAYROLL_API_CAPABILITY_CONFIRMED')
165	        ? 'Payroll API sync is enabled without explicit capability confirmation.'
166	        : 'Payroll API sync remains capability-gated.',
167	  });
168	
169	  if (requireAccountMappings) {
170	    const mappingStatus = evaluateRequiredHiloQuickBooksAccountMappings(
171	      input.accountMappings ?? [],
172	    );
173	    for (const definition of HILO_QUICKBOOKS_ACCOUNT_MAPPING_DEFINITIONS) {
174	      const missing = mappingStatus.missingKeys.includes(definition.mappingKey);
175	      checks.push({
176	        key: `account_mapping.${definition.mappingKey}`,
177	        status: missing ? 'FAIL' : 'PASS',
178	        severity: 'BLOCKER',
179	        message: missing
180	          ? `Hilo QuickBooks account mapping missing for ${definition.displayName}.`
181	          : `Hilo QuickBooks account mapping configured for ${definition.displayName}.`,
182	      });
183	    }
184	  }
185	
186	  if (requireFinanceSignoff) {
187	    const approved = new Set(
188	      (input.financeSignoffs ?? [])
189	        .filter(
190	          (signoff) =>
191	            signoff.status === 'APPROVED' && Boolean(signoff.approvedAt),
192	        )
193	        .map((signoff) => signoff.signoffKey),
194	    );
195	
196	    for (const key of HILO_FINANCE_SIGNOFF_KEYS) {
197	      checks.push({
198	        key: `finance_signoff.${key}`,
199	        status: approved.has(key) ? 'PASS' : 'FAIL',
200	        severity: 'BLOCKER',
201	        message: approved.has(key)
202	          ? `Finance approved ${key}.`
203	          : `Finance signoff missing for ${key}.`,
204	      });
205	    }
206	  }
207	
208	  const blockers = checks.filter(
209	    (check) => check.status === 'FAIL' && check.severity === 'BLOCKER',
210	  );
211	
212	  return {
213	    ready: blockers.length === 0,
214	    checks,
215	    blockers,
216	    quickBooksWritesEnabled,
217	    requireFinanceSignoff,
218	    requireAccountMappings,
219	  };
220	}
