295	export async function assertAccountingProductionReady(input: {
296	  owner: AccountingOwnerScope;
297	  env?: Record<string, string | undefined>;
298	  requireStripe?: boolean;
299	  requireQuickBooksWrites?: boolean;
300	  requireFinanceSignoff?: boolean;
