2	  type AccountingOwnerType,
3	  type AccountingProvider,
4	  buildIntegrationObjectMappingKey,
5	} from './owner-scope';
6	
7	type LegacyProviderRecord = {
8	  id: string;
9	  ownerType?: AccountingOwnerType | null;
10	  ownerId?: string | null;
11	  provider: AccountingProvider;
12	  providerAccountId?: string | null;
13	  externalObjectType: string;
14	  externalObjectId?: string | null;
15	  internalObjectType?: string | null;
16	  internalObjectId?: string | null;
17	  sourceTable: string;
18	};
19	
20	type ExistingMappingRecord = {
21	  ownerType: AccountingOwnerType;
22	  ownerId: string;
23	  provider: AccountingProvider;
24	  providerAccountId: string;
25	  externalObjectType: string;
26	  externalObjectId: string;
27	  internalObjectType: string;
