30	
31	export interface AccountingBackfillDryRunInput {
32	  legacyStripeCustomers?: LegacyProviderRecord[];
33	  legacyStripeInvoices?: LegacyProviderRecord[];
34	  legacyStripePayments?: LegacyProviderRecord[];
35	  legacyQuickBooksEntities?: LegacyProviderRecord[];
36	  legacyUserScopedQuickBooksIntegrations?: LegacyProviderRecord[];
37	  existingMappings?: ExistingMappingRecord[];
38	}
39	
40	export interface AccountingBackfillDryRunReport {
41	  duplicateLegacyMappings: Array<{
42	    key: string;
43	    records: LegacyProviderRecord[];
44	  }>;
45	  unmappedStripeCustomers: LegacyProviderRecord[];
46	  unmappedStripeInvoices: LegacyProviderRecord[];
47	  unmappedStripePaymentObjects: LegacyProviderRecord[];
48	  unmappedQuickBooksEntities: LegacyProviderRecord[];
49	  legacyUserScopedQuickBooksIntegrations: LegacyProviderRecord[];
50	  recordsRequiringOwnerAssignment: LegacyProviderRecord[];
51	  recordsUnsafeToAutoMigrate: LegacyProviderRecord[];
52	  recommendedAutomaticMigrations: LegacyProviderRecord[];
53	  requiredManualReviewItems: Array<{
54	    reason: string;
55	    record: LegacyProviderRecord;
56	  }>;
57	}
58	
59	function toMappingKey(record: LegacyProviderRecord): string | null {
60	  if (
61	    !record.ownerType ||
62	    !record.ownerId ||
63	    !record.providerAccountId ||
64	    !record.externalObjectId
65	  ) {
66	    return null;
67	  }
68	
69	  return buildIntegrationObjectMappingKey({
70	    ownerType: record.ownerType,
71	    ownerId: record.ownerId,
72	    provider: record.provider,
73	    providerAccountId: record.providerAccountId,
74	    externalObjectType: record.externalObjectType,
75	    externalObjectId: record.externalObjectId,
76	  }).key;
77	}
78	
79	function hasExistingMapping(
80	  record: LegacyProviderRecord,
81	  existingKeys: Set<string>,
82	): boolean {
83	  const key = toMappingKey(record);
84	  return key !== null && existingKeys.has(key);
85	}
86	
87	function needsOwnerAssignment(record: LegacyProviderRecord): boolean {
88	  return !record.ownerType || !record.ownerId || !record.providerAccountId;
89	}
90	
91	function isUnsafe(record: LegacyProviderRecord): boolean {
92	  return (
93	    needsOwnerAssignment(record) ||
94	    !record.externalObjectId ||
95	    !record.internalObjectId ||
96	    !record.internalObjectType
97	  );
98	}
99	
100	function collectDuplicates(records: LegacyProviderRecord[]) {
101	  const grouped = new Map<string, LegacyProviderRecord[]>();
102	  for (const record of records) {
103	    const key = toMappingKey(record);
104	    if (!key) continue;
105	    const group = grouped.get(key) ?? [];
106	    group.push(record);
107	    grouped.set(key, group);
108	  }
109	
110	  return [...grouped.entries()]
111	    .filter(([, recordsForKey]) => recordsForKey.length > 1)
112	    .map(([key, recordsForKey]) => ({ key, records: recordsForKey }));
113	}
114	
115	export function buildAccountingBackfillDryRunReport(
116	  input: AccountingBackfillDryRunInput,
117	): AccountingBackfillDryRunReport {
118	  const existingKeys = new Set(
119	    (input.existingMappings ?? []).map(
120	      (mapping) =>
121	        buildIntegrationObjectMappingKey({
122	          ownerType: mapping.ownerType,
123	          ownerId: mapping.ownerId,
124	          provider: mapping.provider,
125	          providerAccountId: mapping.providerAccountId,
126	          externalObjectType: mapping.externalObjectType,
127	          externalObjectId: mapping.externalObjectId,
128	        }).key,
129	    ),
130	  );
131	
132	  const stripeCustomers = input.legacyStripeCustomers ?? [];
133	  const stripeInvoices = input.legacyStripeInvoices ?? [];
134	  const stripePayments = input.legacyStripePayments ?? [];
135	  const quickBooksEntities = input.legacyQuickBooksEntities ?? [];
136	  const userScopedQuickBooks =
137	    input.legacyUserScopedQuickBooksIntegrations ?? [];
138	  const allLegacy = [
139	    ...stripeCustomers,
140	    ...stripeInvoices,
141	    ...stripePayments,
142	    ...quickBooksEntities,
143	    ...userScopedQuickBooks,
144	  ];
145	  const duplicateLegacyMappings = collectDuplicates(allLegacy);
146	  const duplicateRecordIds = new Set(
147	    duplicateLegacyMappings.flatMap((group) =>
148	      group.records.map((record) => record.id),
149	    ),
150	  );
151	
152	  const recordsRequiringOwnerAssignment =
153	    allLegacy.filter(needsOwnerAssignment);
154	  const recordsUnsafeToAutoMigrate = allLegacy.filter(
155	    (record) => isUnsafe(record) || duplicateRecordIds.has(record.id),
156	  );
157	  const unsafeIds = new Set(
158	    recordsUnsafeToAutoMigrate.map((record) => record.id),
159	  );
160	  const recommendedAutomaticMigrations = allLegacy.filter(
161	    (record) =>
162	      !unsafeIds.has(record.id) && !hasExistingMapping(record, existingKeys),
163	  );
164	  const requiredManualReviewItems = recordsUnsafeToAutoMigrate.map(
165	    (record) => ({
166	      reason: needsOwnerAssignment(record)
167	        ? 'Missing owner/provider-account scope'
168	        : duplicateRecordIds.has(record.id)
169	          ? 'Duplicate owner-scoped provider mapping candidate'
170	          : 'Missing internal or external object identity',
171	      record,
172	    }),
173	  );
174	
175	  return {
176	    duplicateLegacyMappings,
177	    unmappedStripeCustomers: stripeCustomers.filter(
178	      (record) => !hasExistingMapping(record, existingKeys),
179	    ),
180	    unmappedStripeInvoices: stripeInvoices.filter(
181	      (record) => !hasExistingMapping(record, existingKeys),
182	    ),
183	    unmappedStripePaymentObjects: stripePayments.filter(
184	      (record) => !hasExistingMapping(record, existingKeys),
185	    ),
186	    unmappedQuickBooksEntities: quickBooksEntities.filter(
187	      (record) => !hasExistingMapping(record, existingKeys),
188	    ),
189	    legacyUserScopedQuickBooksIntegrations: userScopedQuickBooks,
190	    recordsRequiringOwnerAssignment,
191	    recordsUnsafeToAutoMigrate,
192	    recommendedAutomaticMigrations,
193	    requiredManualReviewItems,
194	  };
195	}
