121	function normalizePaymentMethodType(
122	  method?: { funding?: string | null; brand?: string | null } | null,
123	): PaymentMethodType {
124	  if (!method) return 'unknown';
125	  const funding = method.funding?.toLowerCase();
126	  if (funding === 'bank_account' || funding === 'us_bank_account') {
127	    return 'ach';
128	  }
129	  if (method.brand) return 'card';
130	  return 'unknown';
131	}
