160	function summarizeRows(
161	  rows: Array<{
162	    taxableChargesCents: number;
163	    taxAmountCents: number;
164	    paymentProcessingFeeCents: number;
165	    totalAmountCents: number;
166	  }>,
167	): HiloBillingReportSummary {
168	  return rows.reduce(
169	    (summary, row) => ({
170	      rowCount: summary.rowCount + 1,
171	      taxableChargesCents:
172	        summary.taxableChargesCents + row.taxableChargesCents,
173	      taxAmountCents: summary.taxAmountCents + row.taxAmountCents,
174	      nonTaxableFeesCents:
175	        summary.nonTaxableFeesCents + row.paymentProcessingFeeCents,
176	      totalAmountCents: summary.totalAmountCents + row.totalAmountCents,
177	    }),
178	    {
179	      rowCount: 0,
180	      taxableChargesCents: 0,
181	      taxAmountCents: 0,
182	      nonTaxableFeesCents: 0,
183	      totalAmountCents: 0,
184	    },
185	  );
