249	function deriveBillingRowWorkflowStatus(input: {
250	  persistedStatus?: string | null;
251	  estimated: boolean;
252	  stripeCustomerId?: string | null;
253	  stripeInvoiceId?: string | null;
254	  quickbooksInvoiceId?: string | null;
255	  quickbooksSyncStatus?: string | null;
256	  hasMonthlyPoePeak: boolean;
257	}): { status: BillingRowWorkflowStatus; reasons: string[] } {
258	  const reasons: string[] = [];
259	  if (!input.hasMonthlyPoePeak) {
260	    reasons.push('No monthly POE peak exists for the billing period.');
261	  }
262	  if (!input.stripeCustomerId) {
263	    reasons.push('No Hilo Stripe customer is linked for this flight school.');
264	  }
265	
266	  if (input.persistedStatus === 'EXCEPTION') {
267	    return { status: 'Needs manual resolution', reasons };
268	  }
269	  if (input.quickbooksInvoiceId || input.quickbooksSyncStatus === 'synced') {
270	    return { status: 'Synced to QuickBooks', reasons };
271	  }
272	  if (input.stripeInvoiceId && input.quickbooksSyncStatus) {
273	    return { status: 'Partially synced', reasons };
274	  }
275	  if (input.stripeInvoiceId) {
276	    return { status: 'Sent to Stripe', reasons };
277	  }
278	  if (!input.stripeCustomerId) {
279	    return { status: 'Needs mapping', reasons };
280	  }
281	  if (input.persistedStatus === 'READY') {
282	    return { status: 'Ready to send', reasons };
283	  }
284	  if (input.estimated) {
285	    return { status: 'Estimated', reasons };
286	  }
287	  return { status: 'Ready for review', reasons };
288	}
