290	function getMonthRange(period: string) {
291	  const start = getBillingMonthDate(period);
292	  const end = new Date(
293	    Date.UTC(start.getUTCFullYear(), start.getUTCMonth() + 1, 1),
294	  );
295	  return { start, end };
296	}
