298	async function countPriorOnboardingCharges(subscriberId: string) {
299	  const rows = await db
300	    .select({
301	      onboardingFeeCents: schema.hiloBillingReportRows.onboardingFeeCents,
302	    })
303	    .from(schema.hiloBillingReportRows)
304	    .innerJoin(
305	      schema.hiloBillingReports,
306	      eq(schema.hiloBillingReportRows.reportId, schema.hiloBillingReports.id),
307	    )
308	    .where(
309	      and(
310	        eq(schema.hiloBillingReportRows.subscriberId, subscriberId),
311	        gt(schema.hiloBillingReportRows.onboardingFeeCents, 0),
312	      ),
313	    );
314	  return rows.length;
315	}
