317	export async function generateMonthlyBillingReport(
318	  period: string,
319	  ownerId = DEFAULT_HILO_PLATFORM_OWNER_ID,
320	) {
321	  const billingPeriod = assertBillingPeriod(period);
322	  const billingMonth = getBillingMonthDate(billingPeriod);
323	
324	  const [existing] = await db
325	    .select()
326	    .from(schema.hiloBillingReports)
327	    .where(
328	      and(
329	        eq(schema.hiloBillingReports.ownerType, 'HILO_PLATFORM'),
330	        eq(schema.hiloBillingReports.ownerId, ownerId),
331	        eq(schema.hiloBillingReports.billingPeriod, billingPeriod),
332	      ),
333	    )
334	    .limit(1);
335	
336	  if (existing && existing.status !== 'DRAFT') {
337	    throw new Error(
338	      `Billing report ${billingPeriod} is ${existing.status} and cannot be regenerated`,
339	    );
340	  }
341	
342	  const [subscribers, monthlyPeaks, defaultPaymentMethods, onboardingSettings] =
343	    await Promise.all([
344	      db
345	        .select()
346	        .from(schema.flightSchools)
347	        .where(eq(schema.flightSchools.isTest, false)),
348	      db
349	        .select()
350	        .from(schema.poeMonthlyPeaks)
351	        .where(eq(schema.poeMonthlyPeaks.billingMonth, billingMonth)),
352	      db
353	        .select()
354	        .from(schema.schoolPaymentMethods)
355	        .where(eq(schema.schoolPaymentMethods.isDefault, true)),
356	      db.select().from(schema.onboardingFeeSettings),
357	    ]);
358	
359	  const [paymentFeeSetting] = await db
360	    .select()
361	    .from(schema.paymentFeeSettings)
362	    .where(
363	      and(
364	        eq(schema.paymentFeeSettings.ownerType, 'HILO_PLATFORM'),
365	        eq(schema.paymentFeeSettings.ownerId, ownerId),
366	      ),
367	    )
368	    .limit(1);
369	
370	  const peaksBySchool = new Map(
371	    monthlyPeaks.map((peak) => [peak.flightSchoolId, peak]),
372	  );
373	  const paymentMethodBySchool = new Map(
374	    defaultPaymentMethods.map((method) => [method.flightSchoolId, method]),
375	  );
376	  const onboardingBySchool = new Map(
377	    onboardingSettings.map((setting) => [setting.subscriberId, setting]),
378	  );
379	
380	  const rows = await buildGeneratedBillingRows({
381	    billingPeriod,
382	    subscribers,
383	    peaksBySchool,
384	    paymentMethodBySchool,
385	    onboardingBySchool,
386	    paymentFeeSetting,
387	  });
388	
389	  const summary = summarizeRows(rows);
390	
391	  return withTransaction(async (tx) => {
392	    const [report] = await tx
393	      .insert(schema.hiloBillingReports)
394	      .values({
395	        ownerType: 'HILO_PLATFORM',
396	        ownerId,
397	        billingPeriod,
398	        status: 'DRAFT',
399	        ...summary,
400	      })
401	      .onConflictDoUpdate({
402	        target: [
403	          schema.hiloBillingReports.ownerType,
404	          schema.hiloBillingReports.ownerId,
405	          schema.hiloBillingReports.billingPeriod,
406	        ],
407	        set: {
408	          status: 'DRAFT',
409	          lockedAt: null,
410	          finalizedAt: null,
411	          finalizedByUserId: null,
412	          ...summary,
413	          updatedAt: new Date(),
414	        },
415	      })
416	      .returning();
417	
418	    await tx
419	      .delete(schema.hiloBillingReportRows)
420	      .where(eq(schema.hiloBillingReportRows.reportId, report.id));
421	
422	    const reportRows =
423	      rows.length === 0
424	        ? []
425	        : await tx
426	            .insert(schema.hiloBillingReportRows)
427	            .values(rows.map((row) => ({ ...row, reportId: report.id })))
428	            .returning();
429	
430	    return { report, rows: reportRows, summary };
431	  });
432	}
