434	async function buildGeneratedBillingRows(input: {
435	  billingPeriod: string;
436	  subscribers: Array<typeof schema.flightSchools.$inferSelect>;
437	  peaksBySchool: Map<string, typeof schema.poeMonthlyPeaks.$inferSelect>;
438	  paymentMethodBySchool: Map<
439	    string,
440	    typeof schema.schoolPaymentMethods.$inferSelect
441	  >;
442	  onboardingBySchool: Map<
443	    string,
444	    typeof schema.onboardingFeeSettings.$inferSelect
445	  >;
446	  paymentFeeSetting?: typeof schema.paymentFeeSettings.$inferSelect;
447	}) {
448	  const rows: GeneratedBillingReportRow[] = [];
449	  for (const subscriber of input.subscribers) {
450	    const priorOnboardingPayments = await countPriorOnboardingCharges(
451	      subscriber.id,
452	    );
453	    const preview = calculateSubscriberBillingPreview({
454	      subscriberId: subscriber.id,
455	      period: input.billingPeriod,
456	      highestPoeCount: input.peaksBySchool.get(subscriber.id)?.peakPoe ?? 0,
457	      contractStartDate: subscriber.createdAt,
458	      onboardingPaymentsAlreadyBilled: priorOnboardingPayments,
459	      paymentMethodType: normalizePaymentMethodType(
460	        input.paymentMethodBySchool.get(subscriber.id),
461	      ),
462	      paymentFeeSettings: toPaymentFeeSettings(input.paymentFeeSetting),
463	      onboardingSettings: toOnboardingSettings(
464	        input.onboardingBySchool.get(subscriber.id),
465	      ),
466	      taxAmountCents: 0,
467	    });
468	
469	    rows.push({
470	      subscriberId: subscriber.id,
471	      status: 'DRAFT' as const,
472	      highestPoeCount: preview.highestPoeCount,
473	      poeLevel: preview.level.level,
474	      platformFeeCents: preview.platformFeeCents,
475	      onboardingFeeCents: preview.onboardingFeeCents,
476	      monthlyServiceFeeCents: preview.monthlyServiceFeeCents,
477	      monthsLeftInTerm: preview.monthsLeftInTerm,
478	      paymentMethodType: preview.paymentMethodType,
479	      paymentProcessingFeeCents: preview.paymentProcessingFeeCents,
480	      taxableChargesCents: preview.taxableChargesCents,
481	      taxAmountCents: preview.taxAmountCents,
482	      totalAmountCents: preview.invoiceTotalCents,
483	    });
484	  }
485	  return rows;
486	}
