557	async function enrichBillingRows(input: {
558	  ownerId: string;
559	  billingPeriod: string;
560	  rows: Array<
561	    GeneratedBillingReportRow & {
562	      id: string;
563	      reportId: string | null;
564	      stripeInvoiceId: string | null;
565	      quickbooksInvoiceId: string | null;
566	    }
567	  >;
568	  estimated: boolean;
569	}): Promise<EnrichedBillingReportRow[]> {
570	  const { start, end } = getMonthRange(input.billingPeriod);
571	  const [
572	    schools,
573	    billingConfigs,
574	    stripeIntegrations,
575	    monthlyPeaks,
576	    recentInvoices,
577	    stripeHistoryRows,
578	    quickBooksHistoryRows,
579	    reconciliationFindings,
580	  ] = await Promise.all([
581	    db.select().from(schema.flightSchools),
582	    db.select().from(schema.billingConfig),
583	    db.select().from(schema.schoolStripeIntegrations),
584	    db
585	      .select()
586	      .from(schema.poeMonthlyPeaks)
587	      .where(eq(schema.poeMonthlyPeaks.billingMonth, start)),
588	    db
589	      .select()
590	      .from(schema.invoices)
591	      .where(
592	        and(
593	          sql`${schema.invoices.periodStart} < ${end}`,
594	          sql`${schema.invoices.periodEnd} >= ${start}`,
595	        ),
596	      )
597	      .orderBy(desc(schema.invoices.createdAt)),
598	    db
599	      .select()
600	      .from(schema.accountingStripeHistory)
601	      .where(
602	        and(
603	          eq(schema.accountingStripeHistory.ownerType, 'HILO_PLATFORM'),
604	          eq(schema.accountingStripeHistory.ownerId, input.ownerId),
605	        ),
606	      ),
607	    db
608	      .select()
609	      .from(schema.accountingQuickBooksHistory)
610	      .where(
611	        and(
612	          eq(schema.accountingQuickBooksHistory.ownerType, 'HILO_PLATFORM'),
613	          eq(schema.accountingQuickBooksHistory.ownerId, input.ownerId),
614	        ),
615	      ),
616	    db
617	      .select()
618	      .from(schema.accountingReconciliationFindings)
619	      .where(
620	        and(
621	          eq(
622	            schema.accountingReconciliationFindings.ownerType,
623	            'HILO_PLATFORM',
624	          ),
625	          eq(schema.accountingReconciliationFindings.ownerId, input.ownerId),
626	          eq(schema.accountingReconciliationFindings.status, 'OPEN'),
627	        ),
628	      ),
629	  ]);
630	
631	  const schoolById = new Map(schools.map((school) => [school.id, school]));
632	  const configBySchool = new Map(
633	    billingConfigs.map((config) => [config.flightSchoolId, config]),
634	  );
635	  const stripeIntegrationBySchool = new Map(
636	    stripeIntegrations.map((integration) => [
637	      integration.flightSchoolId,
638	      integration,
639	    ]),
640	  );
641	  const peakBySchool = new Map(
642	    monthlyPeaks.map((peak) => [peak.flightSchoolId, peak]),
643	  );
644	  const invoiceBySchool = new Map<
645	    string,
646	    typeof schema.invoices.$inferSelect
647	  >();
648	  for (const invoice of recentInvoices) {
649	    if (!invoiceBySchool.has(invoice.flightSchoolId)) {
650	      invoiceBySchool.set(invoice.flightSchoolId, invoice);
651	    }
652	  }
653	  const stripeCustomerBySchool = new Map<
654	    string,
655	    typeof schema.accountingStripeHistory.$inferSelect
656	  >();
657	  const stripeSubscriptionBySchool = new Map<
658	    string,
659	    typeof schema.accountingStripeHistory.$inferSelect
660	  >();
661	  const stripeInvoiceById = new Map<
662	    string,
663	    typeof schema.accountingStripeHistory.$inferSelect
664	  >();
665	  const stripeInvoiceByInternalId = new Map<
666	    string,
667	    typeof schema.accountingStripeHistory.$inferSelect
668	  >();
669	  for (const history of stripeHistoryRows) {
670	    if (history.providerObjectType === 'customer') {
671	      stripeCustomerBySchool.set(history.flightSchoolId, history);
672	    }
673	    if (
674	      history.providerObjectType === 'subscription' &&
675	      history.subscriptionStatus === 'active'
676	    ) {
