128	function assertIntegerCents(value: number, field: string): number {
129	  if (!Number.isFinite(value) || !Number.isInteger(value) || value < 0) {
130	    throw new Error(`${field} must be a non-negative integer`);
131	  }
132	  return value;
133	}
134	
135	function normalizePoeCount(poeCount: number): number {
136	  if (!Number.isFinite(poeCount) || poeCount < 0) {
137	    throw new Error('highestPoeCount must be a non-negative number');
138	  }
139	  return Math.floor(poeCount);
140	}
141	
142	function parsePeriodStart(period: string): Date {
143	  if (!/^\d{4}-\d{2}$/.test(period)) {
144	    throw new Error('period must use YYYY-MM format');
145	  }
146	  const [year, month] = period.split('-').map(Number);
147	  return new Date(Date.UTC(year, month - 1, 1));
148	}
149	
150	function monthIndex(date: Date): number {
151	  return date.getUTCFullYear() * 12 + date.getUTCMonth();
152	}
153	
154	export function getPoeBillingLevel(poeCountInput: number): PoeBillingLevel {
155	  const poeCount = normalizePoeCount(poeCountInput);
156	  if (poeCount < 20) return POE_BILLING_LEVELS[0];
157	  const level = POE_BILLING_LEVELS.find(
158	    (candidate) =>
159	      poeCount >= candidate.minPoe &&
160	      (candidate.maxPoe === null || poeCount <= candidate.maxPoe),
161	  );
162	  if (!level) {
163	    throw new Error(`Unable to resolve POE level for count ${poeCount}`);
164	  }
165	  return level;
166	}
