168	export function calculateMonthsLeftInTerm(input: {
169	  contractStartDate: string | Date;
170	  period: string;
171	  termMonths?: number;
172	}): number {
173	  const termMonths = input.termMonths ?? CONTRACT_TERM_MONTHS;
174	  const start =
175	    input.contractStartDate instanceof Date
176	      ? input.contractStartDate
177	      : new Date(input.contractStartDate);
178	  if (Number.isNaN(start.getTime())) {
179	    throw new Error('contractStartDate must be a valid date');
180	  }
181	
182	  const periodStart = parsePeriodStart(input.period);
183	  const elapsedMonths = Math.max(
184	    0,
185	    monthIndex(periodStart) - monthIndex(start),
186	  );
187	  return Math.max(0, Math.min(termMonths, termMonths - elapsedMonths));
188	}
