190	export function calculateOnboardingFeeDue(input: {
191	  level: PoeBillingLevel;
192	  settings?: OnboardingFeeSettingsInput;
193	  paymentsAlreadyBilled?: number;
194	}): number {
195	  const configuredTotal =
196	    input.settings?.onboardingFeeTotalCents ?? input.level.onboardingFeeCents;
197	  const total = assertIntegerCents(configuredTotal, 'onboardingFeeTotalCents');
198	  if (total === 0) return 0;
199	
200	  const defaultPayments = Math.max(1, input.level.onboardingMonths || 1);
201	  const numberOfPayments = Math.max(
202	    1,
203	    Math.floor(input.settings?.numberOfPayments ?? defaultPayments),
204	  );
205	  const paymentsAlreadyBilled = Math.max(
206	    0,
207	    Math.floor(input.paymentsAlreadyBilled ?? 0),
208	  );
209	  if (paymentsAlreadyBilled >= numberOfPayments) return 0;
210	
211	  const base = Math.floor(total / numberOfPayments);
212	  const remainder = total % numberOfPayments;
213	  return base + (paymentsAlreadyBilled < remainder ? 1 : 0);
214	}
