216	export function calculatePaymentProcessingFee(input: {
217	  methodType?: PaymentMethodType;
218	  applicableTotalCents: number;
219	  settings?: PaymentFeeSettingsInput;
220	}): PaymentProcessingFeeResult {
221	  const applicableTotalCents = assertIntegerCents(
222	    input.applicableTotalCents,
223	    'applicableTotalCents',
224	  );
225	  const methodType = input.methodType ?? 'unknown';
226	  const settings = input.settings ?? {};
227	  const displayMode = settings.feeDisplayMode ?? 'line_item';
228	
229	  if (
230	    methodType === 'ach' ||
231	    methodType === 'us_bank_account' ||
232	    methodType === 'bank_account'
233	  ) {
234	    const enabled = settings.achFeeEnabled ?? true;
235	    return {
236	      amountCents: enabled ? (settings.achFlatFeeAmountCents ?? 500) : 0,
237	      methodType,
238	      taxable: false,
239	      configuredFeeTaxable: settings.feeTaxable ?? false,
240	      displayMode,
241	    };
242	  }
243	
244	  if (methodType === 'card' || methodType === 'credit_card') {
245	    const enabled = settings.cardFeeEnabled ?? true;
246	    const percentage = settings.cardPercentage ?? 2.9;
247	    const fixedCents = settings.cardFixedFeeCents ?? 30;
248	    return {
249	      amountCents: enabled
250	        ? Math.round((applicableTotalCents * percentage) / 100) + fixedCents
251	        : 0,
252	      methodType,
253	      taxable: false,
254	      configuredFeeTaxable: settings.feeTaxable ?? false,
255	      displayMode,
256	    };
257	  }
258	
259	  return {
260	    amountCents: 0,
261	    methodType,
262	    taxable: false,
263	    configuredFeeTaxable: settings.feeTaxable ?? false,
264	    displayMode,
265	  };
266	}
