268	export function calculateSubscriberBillingPreview(
269	  input: SubscriberBillingPreviewInput,
270	): SubscriberBillingPreview {
271	  const highestPoeCount = normalizePoeCount(input.highestPoeCount);
272	  const level = getPoeBillingLevel(highestPoeCount);
273	  const platformFeeCents = highestPoeCount * level.platformFeePerPoeCents;
274	  const onboardingFeeCents = calculateOnboardingFeeDue({
275	    level,
276	    settings: input.onboardingSettings,
277	    paymentsAlreadyBilled: input.onboardingPaymentsAlreadyBilled,
278	  });
279	  const monthlyServiceFeeCents = level.monthlyServiceFeeCents;
280	  const taxableChargesCents =
281	    platformFeeCents + onboardingFeeCents + monthlyServiceFeeCents;
282	  const taxAmountCents = assertIntegerCents(
283	    input.taxAmountCents ?? 0,
284	    'taxAmountCents',
285	  );
286	  const paymentFee = calculatePaymentProcessingFee({
287	    methodType: input.paymentMethodType,
288	    applicableTotalCents: taxableChargesCents + taxAmountCents,
289	    settings: input.paymentFeeSettings,
290	  });
291	  const nonTaxableFeeCents = paymentFee.amountCents;
292	
293	  const lineItems: BillingLineItem[] = [
294	    {
295	      code: 'platform_fee',
296	      description: `Platform fee (${highestPoeCount} POE)`,
297	      amountCents: platformFeeCents,
298	      taxable: true,
299	    },
300	  ];
301	  if (onboardingFeeCents > 0) {
302	    lineItems.push({
303	      code: 'onboarding_fee',
304	      description: 'Onboarding fee',
305	      amountCents: onboardingFeeCents,
306	      taxable: true,
307	    });
308	  }
309	  if (monthlyServiceFeeCents > 0) {
310	    lineItems.push({
311	      code: 'monthly_service_fee',
312	      description: 'Monthly service fee',
313	      amountCents: monthlyServiceFeeCents,
314	      taxable: true,
315	    });
316	  }
317	  if (paymentFee.amountCents > 0) {
318	    lineItems.push({
319	      code: 'payment_processing_fee',
320	      description: 'Payment processing fee',
321	      amountCents: paymentFee.amountCents,
322	      taxable: false,
323	    });
324	  }
325	
326	  return {
327	    subscriberId: input.subscriberId,
328	    period: input.period,
329	    level,
330	    highestPoeCount,
331	    platformFeeCents,
332	    onboardingFeeCents,
333	    monthlyServiceFeeCents,
334	    monthsLeftInTerm: calculateMonthsLeftInTerm({
335	      contractStartDate: input.contractStartDate,
336	      period: input.period,
337	    }),
338	    paymentProcessingFeeCents: paymentFee.amountCents,
339	    taxableChargesCents,
340	    taxAmountCents,
341	    nonTaxableFeeCents,
342	    invoiceTotalCents:
343	      taxableChargesCents + taxAmountCents + nonTaxableFeeCents,
344	    paymentMethodType: paymentFee.methodType,
345	    lineItems,
346	  };
347	}
