237	export async function createStripeInvoiceForBillingRow(reportRowId: string) {
238	  const record = await loadBillingRow(reportRowId);
239	  const ownerId = record.report.ownerId;
240	  if (shouldEnforceAccountingProductionReadiness()) {
241	    await assertAccountingProductionReady({
242	      owner: { ownerType: 'HILO_PLATFORM', ownerId },
243	      requireStripe: true,
244	      requireFinanceSignoff: true,
245	    });
246	  }
247	  const stripeCustomerId = await createOrReuseStripeCustomer(record);
248	
249	  if (record.row.stripeInvoiceId) {
250	    return { stripeInvoiceId: record.row.stripeInvoiceId, reused: true };
251	  }
252	
253	  if (
254	    record.row.paymentProcessingFeeCents > 0 &&
255	    !PAYMENT_FEE_NONTAXABLE_TAX_CODE
256	  ) {
257	    throw new Error(
258	      'STRIPE_PAYMENT_FEE_NONTAXABLE_TAX_CODE is required before adding non-taxable processing fee lines',
259	    );
260	  }
261	
262	  const invoiceIdempotency = buildProviderIdempotencyKey({
263	    ownerType: 'HILO_PLATFORM',
264	    ownerId,
265	    provider: 'STRIPE',
266	    providerAccountId: HILO_STRIPE_PROVIDER_ACCOUNT_ID,
267	    operation: 'invoice.create',
268	    objectType: 'hilo_billing_report_row',
269	    objectId: reportRowId,
270	  });
271	
272	  try {
273	    const invoice = await hiloBillingStripe.createInvoice(
274	      {
275	        customer: stripeCustomerId,
276	        collection_method: 'charge_automatically',
277	        auto_advance: false,
278	        automatic_tax: { enabled: true },
279	        metadata: {
280	          ownerType: 'HILO_PLATFORM',
281	          ownerId,
282	          billingPeriod: record.report.billingPeriod,
283	          reportId: record.report.id,
284	          reportRowId,
285	          subscriberId: record.school.id,
286	          peakPoe: String(record.row.highestPoeCount),
287	        },
288	      },
289	      { idempotencyKey: invoiceIdempotency.idempotencyKey },
290	    );
291	
292	    for (const item of taxableLineItems(record.row)) {
293	      const idempotency = buildProviderIdempotencyKey({
294	        ownerType: 'HILO_PLATFORM',
295	        ownerId,
296	        provider: 'STRIPE',
297	        providerAccountId: HILO_STRIPE_PROVIDER_ACCOUNT_ID,
298	        operation: 'invoice_item.create',
299	        objectType: 'hilo_billing_report_row',
300	        objectId: reportRowId,
301	        phase: item.code,
302	      });
303	
304	      const params: Stripe.InvoiceItemCreateParams = {
305	        customer: stripeCustomerId,
306	        invoice: invoice.id,
307	        amount: item.amountCents,
308	        currency: 'usd',
309	        description: lineItemDescription(item.code, record.row),
310	        tax_behavior: 'exclusive',
311	        metadata: {
312	          ownerType: 'HILO_PLATFORM',
313	          ownerId,
314	          billingPeriod: record.report.billingPeriod,
315	          reportRowId,
316	          lineItemCode: item.code,
317	          taxable: String(item.taxable),
318	        },
319	      };
320	      if (!item.taxable) {
321	        params.tax_code = PAYMENT_FEE_NONTAXABLE_TAX_CODE;
322	      }
323	
324	      await hiloBillingStripe.createInvoiceItem(params, {
325	        idempotencyKey: idempotency.idempotencyKey,
326	      });
327	    }
328	
329	    await withTransaction(async (tx) => {
330	      await tx
331	        .update(schema.hiloBillingReportRows)
332	        .set({
333	          status: 'STRIPE_INVOICED',
334	          stripeInvoiceId: invoice.id,
335	          updatedAt: new Date(),
336	        })
337	        .where(eq(schema.hiloBillingReportRows.id, reportRowId));
338	      await tx.insert(schema.accountingAuditLogs).values(
339	        buildAccountingAuditLog({
340	          ownerType: 'HILO_PLATFORM',
341	          ownerId,
342	          provider: 'STRIPE',
343	          action: 'stripe.invoice.created',
344	          objectType: 'hilo_billing_report_row',
345	          internalObjectId: reportRowId,
346	          externalObjectId: invoice.id,
347	          metadata: { billingPeriod: record.report.billingPeriod },
348	        }),
349	      );
350	    });
351	
352	    await insertStripeMapping({
353	      ownerId,
354	      reportRowId,
355	      stripeInvoiceId: invoice.id,
356	    });
357	
358	    return { stripeInvoiceId: invoice.id, reused: false };
359	  } catch (error) {
360	    const exception = await createAccountingException({
361	      ownerId,
362	      objectType: 'hilo_billing_report_row',
363	      internalObjectId: reportRowId,
364	      errorCode: 'STRIPE_INVOICE_CREATE_FAILED',
365	      errorMessage: error instanceof Error ? error.message : String(error),
366	    });
367	    await db
368	      .update(schema.hiloBillingReportRows)
369	      .set({ status: 'EXCEPTION', exceptionId: exception.id })
370	      .where(eq(schema.hiloBillingReportRows.id, reportRowId));
371	    throw error;
372	  }
373	}
