423	export async function pushBillingReportToStripe(
424	  period: string,
425	  ownerId = DEFAULT_HILO_PLATFORM_OWNER_ID,
426	) {
427	  const [report] = await db
428	    .select()
429	    .from(schema.hiloBillingReports)
430	    .where(
431	      and(
432	        eq(schema.hiloBillingReports.ownerType, 'HILO_PLATFORM'),
433	        eq(schema.hiloBillingReports.ownerId, ownerId),
434	        eq(schema.hiloBillingReports.billingPeriod, period),
435	      ),
436	    )
437	    .limit(1);
438	
439	  if (!report) throw new Error(`Billing report not found for ${period}`);
440	  assertHiloBillingReportActionAllowed(
441	    'push-to-stripe',
442	    isHiloBillingReportStatus(report.status) ? report.status : undefined,
443	    period,
444	  );
445	
446	  const rows = await db
447	    .select()
448	    .from(schema.hiloBillingReportRows)
449	    .where(eq(schema.hiloBillingReportRows.reportId, report.id));
450	
451	  const results = [];
452	  for (const row of rows) {
453	    results.push(await createStripeInvoiceForBillingRow(row.id));
454	  }
455	
456	  const [updatedReport] = await db
457	    .update(schema.hiloBillingReports)
458	    .set({ status: 'PUSHED_TO_STRIPE', updatedAt: new Date() })
459	    .where(eq(schema.hiloBillingReports.id, report.id))
460	    .returning();
461	
462	  const updatedRows = await db
463	    .select()
464	    .from(schema.hiloBillingReportRows)
465	    .where(eq(schema.hiloBillingReportRows.reportId, report.id));
466	
467	  return {
468	    reportId: report.id,
469	    period,
470	    report: updatedReport ?? report,
471	    rows: updatedRows,
472	    results,
473	  };
474	}
