9	const QUICKBOOKS_REFRESH_BUFFER_MS = 5 * 60 * 1000;
10	
11	function hashToInt(str: string): number {
12	  let hash = 0;
13	  for (let i = 0; i < str.length; i++) {
14	    hash = (hash << 5) - hash + str.charCodeAt(i);
15	    hash |= 0;
16	  }
17	  return Math.abs(hash);
18	}
19	
20	function accessTokenExpiresAt(expiresInSeconds: number): Date {
21	  const bufferedSeconds = Math.max(expiresInSeconds - 300, 60);
22	  return new Date(Date.now() + bufferedSeconds * 1000);
23	}
24	
25	function refreshTokenExpiresAt(
26	  expiresInSeconds: number | undefined,
27	  fallback: Date | null,
28	): Date | null {
29	  if (typeof expiresInSeconds === 'number' && expiresInSeconds > 0) {
30	    return new Date(Date.now() + expiresInSeconds * 1000);
31	  }
32	  return fallback;
33	}
