80	async function refreshOwnerQuickBooksToken(input: {
81	  ownerId: string;
82	  connectionId: string;
83	  providerAccountId: string;
84	  realmId: string;
85	}): Promise<string> {
86	  const lockKey = hashToInt(
87	    `accounting-provider:${input.ownerId}:${input.providerAccountId}:${input.realmId}`,
88	  );
89	
90	  return db.transaction(async (tx) => {
91	    await tx.execute(sql`SELECT pg_advisory_xact_lock(${lockKey})`);
92	
93	    const [freshConnection] = await tx
94	      .select()
95	      .from(schema.accountingProviderConnections)
96	      .where(eq(schema.accountingProviderConnections.id, input.connectionId))
97	      .limit(1);
98	    if (!freshConnection || freshConnection.status !== 'active') {
99	      throw new Error('QuickBooks connection is no longer active');
100	    }
101	    if (
102	      freshConnection.oauthAccessTokenEncrypted &&
103	      freshConnection.oauthAccessTokenExpiresAt &&
104	      freshConnection.oauthAccessTokenExpiresAt.getTime() - Date.now() >
105	        QUICKBOOKS_REFRESH_BUFFER_MS
106	    ) {
107	      return decryptQBToken(freshConnection.oauthAccessTokenEncrypted);
108	    }
109	    if (!freshConnection.oauthRefreshTokenEncrypted) {
110	      throw new Error('QuickBooks connection is missing refresh token');
111	    }
112	    if (
113	      freshConnection.oauthRefreshTokenExpiresAt &&
114	      freshConnection.oauthRefreshTokenExpiresAt.getTime() <= Date.now()
115	    ) {
116	      throw new Error('QuickBooks refresh token expired');
117	    }
118	
119	    const tokens = await refreshAccessToken(
120	      decryptQBToken(freshConnection.oauthRefreshTokenEncrypted),
121	    );
122	    const now = new Date();
123	    await tx
124	      .update(schema.accountingProviderConnections)
125	      .set({
126	        oauthAccessTokenEncrypted: encryptQBToken(tokens.access_token),
127	        oauthRefreshTokenEncrypted: encryptQBToken(tokens.refresh_token),
128	        oauthAccessTokenExpiresAt: accessTokenExpiresAt(tokens.expires_in),
129	        oauthRefreshTokenExpiresAt: refreshTokenExpiresAt(
130	          tokens.x_refresh_token_expires_in,
131	          freshConnection.oauthRefreshTokenExpiresAt,
132	        ),
133	        lastOAuthRefreshAt: now,
134	        reconnectRequiredAt: null,
135	        status: 'active',
136	        updatedAt: now,
137	      })
138	      .where(eq(schema.accountingProviderConnections.id, input.connectionId));
139	    await tx.insert(schema.accountingAuditLogs).values(
140	      buildAccountingAuditLog({
141	        ownerType: 'HILO_PLATFORM',
142	        ownerId: input.ownerId,
143	        provider: 'QUICKBOOKS',
144	        action: 'quickbooks.oauth.refreshed',
145	        objectType: 'accounting_provider_connection',
146	        internalObjectId: input.connectionId,
147	        externalObjectId: input.providerAccountId,
148	        metadata: { realmId: input.realmId },
149	      }),
150	    );
151	    return tokens.access_token;
152	  });
153	}
