155	export async function getValidOwnerQuickBooksAccess(input: {
156	  ownerId: string;
157	}) {
158	  const connection = await loadActiveOwnerQuickBooksConnection(input.ownerId);
159	  if (!connection) {
160	    throw new Error('No active owner-scoped Hilo QuickBooks connection found.');
161	  }
162	  if (!connection.intuitRealmId) {
163	    await markReconnectRequired({
164	      ownerId: input.ownerId,
165	      connectionId: connection.id,
166	      providerAccountId: connection.providerAccountId,
167	      reason: 'Missing Intuit realm ID',
168	    });
169	    throw new Error('QuickBooks connection is missing realm ID');
170	  }
171	  if (!connection.oauthAccessTokenEncrypted) {
172	    await markReconnectRequired({
173	      ownerId: input.ownerId,
174	      connectionId: connection.id,
175	      providerAccountId: connection.providerAccountId,
176	      reason: 'Missing access token',
177	    });
178	    throw new Error('QuickBooks connection is missing access token');
179	  }
180	
181	  if (
182	    connection.oauthAccessTokenExpiresAt &&
183	    connection.oauthAccessTokenExpiresAt.getTime() - Date.now() >
184	      QUICKBOOKS_REFRESH_BUFFER_MS
185	  ) {
186	    return {
187	      connection,
188	      realmId: connection.intuitRealmId,
189	      providerAccountId: connection.providerAccountId,
190	      accessToken: decryptQBToken(connection.oauthAccessTokenEncrypted),
191	    };
192	  }
193	
194	  try {
195	    const accessToken = await refreshOwnerQuickBooksToken({
196	      ownerId: input.ownerId,
197	      connectionId: connection.id,
198	      providerAccountId: connection.providerAccountId,
199	      realmId: connection.intuitRealmId,
200	    });
201	    const refreshedConnection =
202	      (await loadActiveOwnerQuickBooksConnection(input.ownerId)) ?? connection;
203	    return {
204	      connection: refreshedConnection,
205	      realmId: connection.intuitRealmId,
206	      providerAccountId: connection.providerAccountId,
207	      accessToken,
208	    };
209	  } catch (error) {
210	    await markReconnectRequired({
211	      ownerId: input.ownerId,
212	      connectionId: connection.id,
213	      providerAccountId: connection.providerAccountId,
214	      reason: error instanceof Error ? error.message : String(error),
215	    });
216	    throw error;
217	  }
218	}
