220	export async function queryOwnerQuickBooks<T>(
221	  ownerId: string,
222	  query: string,
223	): Promise<{
224	  rows: T[];
225	  connection: typeof schema.accountingProviderConnections.$inferSelect;
226	}> {
227	  const auth = await getValidOwnerQuickBooksAccess({ ownerId });
228	  const body = await qbClient.query<Record<string, T[] | number>>(
229	    auth.accessToken,
230	    auth.realmId,
231	    query,
232	  );
233	  const values = Object.values(body.QueryResponse ?? {}).find(Array.isArray);
234	  return {
235	    rows: Array.isArray(values) ? (values as T[]) : [],
236	    connection: auth.connection,
237	  };
238	}
