226	export async function buildTaxJurisdictionSuggestions(input: {
227	  tax: TaxDetailRow;
228	  invoice: InvoiceRow;
229	  school: FlightSchoolRow;
230	  quickbooksHistory?:
231	    | typeof schema.accountingQuickBooksHistory.$inferSelect
232	    | null;
233	}): Promise<TaxJurisdictionSuggestion[]> {
234	  const suggestions: TaxJurisdictionSuggestion[] = [];
235	  const mappings = await activeManualMappings({
236	    billingTaxDetailId: input.tax.id,
237	    flightSchoolId: input.school.id,
238	  });
239	  for (const mapping of mappings) {
240	    if (
241	      mapping.billingTaxDetailId &&
242	      mapping.billingTaxDetailId !== input.tax.id
243	    ) {
244	      continue;
245	    }
246	    suggestions.push({
247	      jurisdictionCode: mapping.jurisdictionCode,
248	      jurisdictionName: mapping.jurisdictionName ?? mapping.jurisdictionCode,
249	      source:
250	        mapping.source === 'MANUAL_ADMIN_MAPPING'
251	          ? 'MANUAL'
252	          : (mapping.source as TaxJurisdictionSuggestion['source']),
253	      confidence: mapping.confidence,
254	      reason: 'Suggested from an active jurisdiction mapping.',
255	      providerObjectId:
256	        mapping.stripeInvoiceId ?? mapping.quickbooksObjectId ?? null,
257	    });
258	  }
259	
260	  const qbSuggestion = extractQuickBooksJurisdiction(
261	    input.quickbooksHistory ?? null,
262	  );
263	  if (qbSuggestion) suggestions.push(qbSuggestion);
264	
265	  const schoolSuggestion = suggestionFromState({
266	    source: 'FLIGHT_SCHOOL_ADDRESS',
267	    state: input.school.state,
268	    confidence:
269	      input.school.address && input.school.city && input.school.zip ? 70 : 45,
270	    reason: 'Suggested from the flight school billing address.',
271	    addressInputs: addressFromSchool(input.school),
272	  });
273	  if (schoolSuggestion) suggestions.push(schoolSuggestion);
274	
275	  const seen = new Set<string>();
276	  return suggestions.filter((suggestion) => {
277	    const key = `${suggestion.source}:${suggestion.jurisdictionCode}`;
278	    if (seen.has(key)) return false;
279	    seen.add(key);
280	    return true;
281	  });
282	}
