333	      reason:
334	        taxLocation?.source != null
335	          ? `Suggested from Stripe Tax customer location (${taxLocation.source}).`
336	          : 'Suggested from Stripe invoice customer address.',
337	      confidence: taxLocation?.state ? 95 : 75,
338	      providerObjectId: row.invoice.stripeInvoiceId,
339	      addressInputs: addressFromStripeInvoice(stripeInvoice),
340	    }) ??
341	    (taxLocation?.country
342	      ? {
343	          jurisdictionCode: taxLocation.country,
344	          jurisdictionName: taxLocation.country,
345	          source: 'STRIPE_TAX' as const,
346	          confidence: 60,
347	          reason: 'Suggested from Stripe Tax country-level customer location.',
348	          providerObjectId: row.invoice.stripeInvoiceId,
349	          addressInputs: addressFromStripeInvoice(stripeInvoice),
