380	export async function applyTaxJurisdictionMapping(input: {
381	  billingTaxDetailId: string;
382	  jurisdictionCode: string;
383	  jurisdictionName?: string | null;
384	  source: string;
385	  confidence?: number;
386	  confirmed: boolean;
387	  actorUserId?: string | null;
388	  metadata?: Record<string, unknown>;
389	}) {
390	  if (!input.confirmed) {
391	    throw new Error(
392	      'Applying tax jurisdiction mappings requires explicit admin confirmation.',
393	    );
394	  }
395	  const row = await loadTaxRemediationRow(input.billingTaxDetailId);
396	  const jurisdictionCode = input.jurisdictionCode.trim().toUpperCase();
397	  if (!jurisdictionCode) throw new Error('jurisdictionCode is required');
398	
399	  const now = new Date();
400	  const [audit] = await db
401	    .insert(schema.accountingAuditLogs)
402	    .values(
403	      buildAccountingAuditLog({
404	        ownerType: 'HILO_PLATFORM',
405	        ownerId: DEFAULT_HILO_PLATFORM_OWNER_ID,
406	        provider: 'STRIPE',
407	        action: 'tax_jurisdiction.mapping_applied',
408	        objectType: 'billing_tax_details',
409	        internalObjectId: row.tax.id,
410	        externalObjectId: row.invoice.stripeInvoiceId,
411	        actorUserId: input.actorUserId ?? null,
412	        metadata: {
413	          beforeTaxJurisdiction: row.tax.taxJurisdiction,
414	          afterTaxJurisdiction: jurisdictionCode,
415	          source: input.source,
416	          confidence: input.confidence ?? 100,
417	          ...input.metadata,
418	        },
419	      }),
420	    )
421	    .returning();
422	
423	  const [mapping] = await db
424	    .insert(schema.accountingTaxJurisdictionMappings)
425	    .values({
426	      ownerType: 'HILO_PLATFORM',
427	      ownerId: DEFAULT_HILO_PLATFORM_OWNER_ID,
428	      flightSchoolId: row.school.id,
429	      billingTaxDetailId: row.tax.id,
430	      stripeInvoiceId: row.invoice.stripeInvoiceId,
431	      quickbooksObjectId: row.quickbooksHistory?.providerObjectId ?? null,
432	      jurisdictionCode,
433	      jurisdictionName: input.jurisdictionName ?? jurisdictionCode,
434	      country: 'US',
435	      state: jurisdictionCode.length === 2 ? jurisdictionCode : null,
436	      source: input.source,
437	      confidence: input.confidence ?? 100,
438	      status: 'ACTIVE',
439	      appliedByUserId: input.actorUserId ?? null,
440	      auditLogId: audit.id,
441	      beforeTaxJurisdiction: row.tax.taxJurisdiction,
442	      afterTaxJurisdiction: jurisdictionCode,
443	      metadata: input.metadata ?? {},
444	      updatedAt: now,
445	    })
446	    .returning();
447	
448	  await db
449	    .update(schema.billingTaxDetails)
450	    .set({ taxJurisdiction: jurisdictionCode, updatedAt: now })
451	    .where(eq(schema.billingTaxDetails.id, row.tax.id));
452	
453	  await db
454	    .update(schema.accountingReconciliationFindings)
455	    .set({ status: 'RESOLVED', resolvedAt: now, lastDetectedAt: now })
456	    .where(
457	      and(
458	        eq(schema.accountingReconciliationFindings.ownerType, 'HILO_PLATFORM'),
459	        eq(
460	          schema.accountingReconciliationFindings.ownerId,
461	          DEFAULT_HILO_PLATFORM_OWNER_ID,
462	        ),
463	        eq(
464	          schema.accountingReconciliationFindings.findingKey,
465	          `tax.jurisdiction.missing:${row.tax.id}`,
466	        ),
467	      ),
468	    );
469	
470	  return { mapping };
471	}
