248	function addPayrollLine(
249	  map: Map<string, PayrollSummaryLine>,
250	  input: Omit<
251	    PayrollSummaryLine,
252	    'sourceEventIds' | 'totalHours' | 'grossPayCents'
253	  > & {
254	    sourceEventId: string;
255	    hours: number;
256	  },
257	) {
258	  if (input.hours <= 0) return;
259	  const key = [
260	    input.instructorId,
261	    input.eventCategory,
262	    input.eventTypeName,
263	  ].join(':');
264	  const existing =
265	    map.get(key) ??
266	    ({
267	      instructorId: input.instructorId,
268	      instructorName: input.instructorName,
269	      instructorEmail: input.instructorEmail,
270	      eventCategory: input.eventCategory,
271	      eventTypeName: input.eventTypeName,
272	      sourceEventIds: [],
273	      totalHours: 0,
274	      payRateCents: input.payRateCents,
275	      grossPayCents: 0,
276	      quickbooksEmployeeId: input.quickbooksEmployeeId,
277	      quickbooksPayTypeId: input.quickbooksPayTypeId,
278	      mappingStatus: input.mappingStatus,
279	    } satisfies PayrollSummaryLine);
280	  existing.sourceEventIds.push(input.sourceEventId);
281	  existing.totalHours = roundHours(existing.totalHours + input.hours);
282	  existing.grossPayCents =
283	    input.eventCategory === 'unpaid'
284	      ? 0
285	      : Math.round(existing.totalHours * existing.payRateCents);
286	  map.set(key, existing);
287	}
