289	export async function buildQuickBooksPayrollSummary(input: {
290	  flightSchoolId: string;
291	  periodStart: Date;
292	  periodEnd: Date;
293	}): Promise<PayrollSummary> {
294	  const instructors = await mvpRepository.users.findBySchoolAndRole(
295	    input.flightSchoolId,
296	    'instructor',
297	  );
298	  const lines = new Map<string, PayrollSummaryLine>();
299	
300	  for (const instructor of instructors) {
301	    const meta = (instructor.instructorMetadata ?? {}) as Record<
302	      string,
303	      unknown
304	    >;
305	    const payRateCents = dollarsToCents(meta.payRate ?? meta.hourlyRate);
306	    const qbEmployeeId =
307	      typeof meta.quickbooksEmployeeId === 'string'
308	        ? meta.quickbooksEmployeeId
309	        : null;
310	    const qbPayTypeId =
311	      typeof meta.quickbooksPayTypeId === 'string'
312	        ? meta.quickbooksPayTypeId
313	        : null;
314	    const mappingStatus = qbEmployeeId ? 'LINKED' : 'UNMAPPED';
315	    const events = await mvpRepository.schedule.findByInstructor(
316	      input.flightSchoolId,
317	      instructor.id,
318	      input.periodStart,
319	      input.periodEnd,
320	    );
321	
322	    for (const event of events) {
323	      if (event.status !== 'completed' && event.status !== 'checked-out') {
324	        continue;
325	      }
326	      const typeName = event.title || event.type || 'Unknown';
327	      const category = classifyQuickBooksPayrollCategory(typeName);
328	      const hours = hobbsHours(event) ?? eventDurationHours(event);
329	      addPayrollLine(lines, {
330	        instructorId: instructor.id,
331	        instructorName: instructor.name,
332	        instructorEmail: instructor.email ?? null,
333	        eventCategory: category,
334	        eventTypeName: typeName,
335	        sourceEventId: event.id,
336	        hours,
337	        payRateCents,
338	        quickbooksEmployeeId: qbEmployeeId,
339	        quickbooksPayTypeId: qbPayTypeId,
340	        mappingStatus,
341	      });
342	
343	      const preFlight = roundHours(Number(event.preFlight ?? 0));
344	      const postFlight = roundHours(Number(event.postFlight ?? 0));
345	      addPayrollLine(lines, {
346	        instructorId: instructor.id,
347	        instructorName: instructor.name,
348	        instructorEmail: instructor.email ?? null,
349	        eventCategory: 'ground',
350	        eventTypeName: 'Pre-Flight Brief',
351	        sourceEventId: `${event.id}:pre`,
352	        hours: preFlight,
353	        payRateCents,
354	        quickbooksEmployeeId: qbEmployeeId,
355	        quickbooksPayTypeId: qbPayTypeId,
356	        mappingStatus,
357	      });
358	      addPayrollLine(lines, {
359	        instructorId: instructor.id,
360	        instructorName: instructor.name,
361	        instructorEmail: instructor.email ?? null,
362	        eventCategory: 'ground',
363	        eventTypeName: 'Post-Flight Brief',
364	        sourceEventId: `${event.id}:post`,
365	        hours: postFlight,
366	        payRateCents,
367	        quickbooksEmployeeId: qbEmployeeId,
368	        quickbooksPayTypeId: qbPayTypeId,
369	        mappingStatus,
370	      });
371	    }
372	  }
373	
374	  const summaryLines = [...lines.values()].sort((a, b) =>
375	    `${a.instructorName}:${a.eventCategory}:${a.eventTypeName}`.localeCompare(
376	      `${b.instructorName}:${b.eventCategory}:${b.eventTypeName}`,
377	    ),
378	  );
379	  return {
380	    flightSchoolId: input.flightSchoolId,
381	    periodStart: input.periodStart,
382	    periodEnd: input.periodEnd,
383	    totalHours: roundHours(
384	      summaryLines.reduce((sum, line) => sum + line.totalHours, 0),
385	    ),
386	    totalGrossPayCents: summaryLines.reduce(
387	      (sum, line) => sum + line.grossPayCents,
388	      0,
389	    ),
390	    lines: summaryLines,
391	  };
392	}
