557	export function buildGrossPayrollJournalEntryPreview(input: {
558	  flightSchoolId: string;
559	  providerAccountId: string;
560	  realmId: string;
561	  summary: PayrollSummary;
562	  mappings: Map<
563	    string,
564	    {
565	      mappingKey: string;
566	      status: string;
567	      externalAccountId?: string | null;
568	      externalAccountName?: string | null;
569	    }
570	  >;
571	}): PayrollJournalEntryPreview {
572	  if (input.summary.periodEnd < input.summary.periodStart) {
573	    throw new Error('Payroll journal preview requires a valid payroll period.');
574	  }
575	
576	  const expense = input.mappings.get(PAYROLL_EXPENSE_MAPPING_KEY);
577	  const liability = input.mappings.get(PAYROLL_LIABILITY_MAPPING_KEY);
578	  if (
579	    expense?.status !== 'ACTIVE' ||
580	    !expense.externalAccountId ||
581	    liability?.status !== 'ACTIVE' ||
582	    !liability.externalAccountId
583	  ) {
584	    throw new Error(
585	      'QuickBooks payroll journal sync requires active payroll_wages_expense and payroll_liability account mappings.',
586	    );
587	  }
588	
589	  const amountCents = input.summary.totalGrossPayCents;
590	  if (amountCents <= 0) {
591	    throw new Error(
592	      'QuickBooks payroll journal sync requires positive gross payroll for the selected period.',
593	    );
594	  }
595	
596	  const period = `${input.summary.periodStart.toISOString().slice(0, 10)}:${input.summary.periodEnd.toISOString().slice(0, 10)}`;
597	  const idempotency = buildProviderIdempotencyKey({
598	    ownerType: 'FLIGHT_SCHOOL',
599	    ownerId: input.flightSchoolId,
600	    provider: 'QUICKBOOKS',
601	    providerAccountId: input.providerAccountId,
602	    operation: 'payroll.journal_entry.create',
603	    objectType: 'payroll_sync_run',
604	    objectId: period,
605	  });
606	
607	  const debitLines: PayrollJournalEntryPreview['debitLines'] = [
608	    {
609	      lineType: 'gross_payroll_wage_expense',
610	      description: `ATOS payroll wages ${period}`,
611	      accountMappingKey: PAYROLL_EXPENSE_MAPPING_KEY,
612	      accountId: expense.externalAccountId,
613	      accountName: expense.externalAccountName ?? null,
614	      amountCents,
615	    },
616	  ];
617	  const creditLines: PayrollJournalEntryPreview['creditLines'] = [
618	    {
619	      lineType: 'gross_payroll_accrual_liability',
620	      description: `ATOS payroll liability ${period}`,
621	      accountMappingKey: PAYROLL_LIABILITY_MAPPING_KEY,
622	      accountId: liability.externalAccountId,
623	      accountName: liability.externalAccountName ?? null,
624	      amountCents,
625	    },
626	  ];
627	  const debitTotal = debitLines.reduce(
628	    (sum, line) => sum + line.amountCents,
629	    0,
630	  );
631	  const creditTotal = creditLines.reduce(
632	    (sum, line) => sum + line.amountCents,
633	    0,
634	  );
635	  if (debitTotal !== creditTotal) {
636	    throw new Error(
637	      `QuickBooks payroll journal entry is unbalanced: debit=${debitTotal} credit=${creditTotal}.`,
638	    );
639	  }
640	
641	  return {
642	    previewType: 'gross_only_fallback',
643	    flightSchoolId: input.flightSchoolId,
644	    providerAccountId: input.providerAccountId,
645	    realmId: input.realmId,
646	    periodStart: input.summary.periodStart.toISOString(),
647	    periodEnd: input.summary.periodEnd.toISOString(),
648	    grossPayrollAmountCents: amountCents,
649	    idempotencyKey: idempotency.idempotencyKey,
650	    idempotencyOperation: 'payroll.journal_entry.create',
651	    privateNote: `ATOS payroll summary ${period} ${idempotency.idempotencyKey}`,
652	    debitLines,
653	    creditLines,
654	    unsupportedDimensionsExcluded: buildUnsupportedPayrollDimensionFindings({
655	      flightSchoolId: input.flightSchoolId,
656	      payrollMode: 'JOURNAL_ENTRY_SYNC',
657	      payrollPeriod: period,
658	    }),
659	    validationResults: PAYROLL_GROSS_FALLBACK_SCOPE.validationRequirements.map(
660	      (check) => ({ check, status: 'passed' as const }),
661	    ),
662	    expectedProviderObjectType: 'journal_entry',
663	  };
664	}
