849	    );
850	  }
851	  if (totals.employerBenefitsDeductionsCents > 0) {
852	    creditLines.push(
853	      journalLine({
854	        lineType: 'employer_benefits_deductions_liability',
855	        description: `ATOS employer benefits/deductions liability ${period}`,
856	        accountMappingKey: 'benefits_deductions_liability',
857	        accountId: benefitLiability.externalAccountId,
858	        accountName: benefitLiability.externalAccountName,
859	        amountCents: totals.employerBenefitsDeductionsCents,
860	      }),
861	    );
862	  }
863	  creditLines.push(
864	    journalLine({
865	      lineType: 'net_pay_payment_clearing',
866	      description: `ATOS net pay/payment clearing ${period}`,
867	      accountMappingKey: 'payment_clearing_cash',
868	      accountId: paymentClearing.externalAccountId,
869	      accountName: paymentClearing.externalAccountName,
870	      amountCents: totals.paymentClearingCents,
871	    }),
872	  );
873	
874	  const debitTotal = debitLines.reduce(
875	    (sum, line) => sum + line.amountCents,
876	    0,
877	  );
878	  const creditTotal = creditLines.reduce(
879	    (sum, line) => sum + line.amountCents,
880	    0,
881	  );
882	  if (debitTotal !== creditTotal) {
883	    throw new Error(
884	      `QuickBooks full payroll journal entry is unbalanced: debit=${debitTotal} credit=${creditTotal}.`,
885	    );
886	  }
887	
888	  return {
889	    previewType: 'full_payroll_journal_entry',
890	    flightSchoolId: input.flightSchoolId,
891	    providerAccountId: input.providerAccountId,
892	    realmId: input.realmId,
893	    periodStart: input.sourceRun.payrollPeriodStart.toISOString(),
894	    periodEnd: input.sourceRun.payrollPeriodEnd.toISOString(),
895	    sourceRunId: input.sourceRun.internalPayrollRunId ?? null,
896	    sourceHash: input.sourceRun.sourceHash,
897	    grossPayrollAmountCents: totals.grossWagesCents,
898	    idempotencyKey: idempotency.idempotencyKey,
899	    idempotencyOperation: 'payroll.full_journal_entry.create',
900	    privateNote: `ATOS full payroll ${period} ${input.sourceRun.sourceHash} ${idempotency.idempotencyKey}`,
901	    debitLines,
902	    creditLines,
903	    unsupportedDimensionsExcluded: [],
904	    validationResults: [
905	      { check: 'ATOS source lines are complete', status: 'passed' },
906	      { check: 'Full payroll mappings are active', status: 'passed' },
907	      { check: 'Debit and credit totals balance', status: 'passed' },
908	      {
