66	function dollarsToCents(value: unknown): number {
67	  const numeric = Number(value ?? 0);
68	  if (!Number.isFinite(numeric)) return 0;
69	  return Math.round(numeric * 100);
70	}
71	
72	function toDateFromSeconds(value: number | null | undefined): Date | null {
73	  return typeof value === 'number' ? new Date(value * 1000) : null;
74	}
75	
76	function parseDate(value: unknown): Date | null {
77	  if (typeof value !== 'string' || value.length === 0) return null;
78	  const parsed = new Date(value);
79	  return Number.isNaN(parsed.getTime()) ? null : parsed;
80	}
81	
82	function rawPayload(value: unknown): Record<string, unknown> {
83	  return JSON.parse(JSON.stringify(value ?? {})) as Record<string, unknown>;
84	}
85	
86	function stripeObjectId(
87	  value: string | { id?: string } | null | undefined,
88	): string | null {
89	  if (!value) return null;
90	  return typeof value === 'string' ? value : (value.id ?? null);
91	}
92	
93	function stripeCustomerStatus(
94	  customer: Stripe.Customer | Stripe.DeletedCustomer,
95	): string {
96	  if ('deleted' in customer && customer.deleted) return 'deleted';
97	  if ('delinquent' in customer && customer.delinquent) return 'delinquent';
98	  return 'active';
99	}
100	
101	function stripeInvoicePaymentStatus(invoice: Stripe.Invoice): string {
102	  if (invoice.status === 'paid') return 'paid';
103	  if ((invoice.amount_paid ?? 0) > 0) return 'partially_paid';
104	  return invoice.status ?? 'unknown';
105	}
106	
107	function stripeInvoicePeriod(invoice: Stripe.Invoice) {
108	  const firstLine = invoice.lines?.data?.[0];
109	  return {
110	    start: toDateFromSeconds(firstLine?.period?.start),
111	    end: toDateFromSeconds(firstLine?.period?.end),
112	  };
113	}
114	
115	function stripeSubscriptionPeriod(subscription: Stripe.Subscription) {
116	  const withPeriod = subscription as Stripe.Subscription & {
117	    current_period_start?: number | null;
118	    current_period_end?: number | null;
119	  };
120	  return {
121	    start: toDateFromSeconds(withPeriod.current_period_start),
122	    end: toDateFromSeconds(withPeriod.current_period_end),
123	  };
124	}
125	
126	function stripeInvoiceSubscriptionId(invoice: Stripe.Invoice): string | null {
127	  const withSubscription = invoice as Stripe.Invoice & {
128	    subscription?: string | { id?: string } | null;
129	  };
130	  return stripeObjectId(withSubscription.subscription);
131	}
132	
133	function stripeInvoiceTaxAmountCents(invoice: Stripe.Invoice): number {
134	  const withTaxes = invoice as Stripe.Invoice & {
135	    total_tax_amounts?: Array<{ amount?: number | null }> | null;
136	  };
137	  return (
138	    withTaxes.total_tax_amounts?.reduce(
139	      (sum: number, tax) => sum + (tax.amount ?? 0),
140	      0,
141	    ) ?? 0
142	  );
143	}
144	
145	function stripeCustomerId(customer: Stripe.Customer | Stripe.DeletedCustomer) {
146	  return customer.id;
147	}
