263	function qbCustomerName(record: Record<string, unknown>): string | null {
264	  const displayName = record.DisplayName;
265	  if (typeof displayName === 'string') return displayName;
266	  const ref = record.CustomerRef as
267	    | { value?: unknown; name?: unknown }
268	    | undefined;
