282	function extractStripeInvoiceId(
283	  record: Record<string, unknown>,
284	): string | null {
285	  const note = extractPrivateNote(record);
286	  const match = note.match(/Stripe:\s*([A-Za-z0-9_]+)/);
287	  return match?.[1] ?? null;
288	}
