290	function extractInternalInvoiceId(
291	  record: Record<string, unknown>,
292	): string | null {
293	  const note = extractPrivateNote(record);
294	  const match = note.match(/Hilo Invoice ID:\s*([0-9a-f-]+)/i);
295	  return match?.[1] ?? null;
296	}
