392	      syncStatus: 'SYNCED',
393	      lastSyncRunId: syncRunId,
394	      lastSyncedAt: syncedAt,
395	    });
396	  }
397	
398	  const normalizeGroup = (
399	    records: Array<Record<string, unknown>>,
400	    providerObjectType: string,
401	  ) => {
402	    for (const record of records) {
