969	export async function runScheduledAccountingProviderHistorySync(input?: {
970	  ownerId?: string;
971	  providers?: Array<'STRIPE' | 'QUICKBOOKS'>;
972	  staleAfterMs?: number;
973	  force?: boolean;
974	}) {
975	  const ownerId = input?.ownerId ?? DEFAULT_HILO_PLATFORM_OWNER_ID;
976	  const providers = input?.providers ?? ['STRIPE', 'QUICKBOOKS'];
977	  const staleAfterMs =
978	    input?.staleAfterMs ?? SCHEDULED_PROVIDER_HISTORY_STALE_MS;
979	  const now = Date.now();
980	  const results: Record<
981	    string,
982	    {
983	      status: 'hydrated' | 'skipped' | 'failed';
984	      reason?: string;
985	      runId?: string | null;
986	    }
987	  > = {};
988	
989	  for (const provider of providers) {
990	    try {
991	      const providerAccountId =
992	        provider === 'STRIPE'
993	          ? HILO_STRIPE_PROVIDER_ACCOUNT_ID
994	          : (await loadActiveOwnerQuickBooksConnection(ownerId))
995	              ?.providerAccountId;
996	      if (!providerAccountId && provider === 'QUICKBOOKS') {
997	        const result = await hydrateQuickBooksAccountingHistory(ownerId);
998	        results[provider] = {
999	          status: 'skipped',
1000	          reason:
1001	            'skipped' in result && result.skipped
1002	              ? 'No active owner-scoped QuickBooks connection'
1003	              : 'QuickBooks sync skipped',
1004	          runId: result.run?.id ?? null,
1005	        };
1006	        continue;
1007	      }
1008	
1009	      const latest = providerAccountId
1010	        ? await latestSuccessfulSyncRun({
1011	            ownerId,
1012	            provider,
1013	            providerAccountId,
1014	            operation: 'history.hydrate',
1015	          })
1016	        : null;
1017	      const fresh =
1018	        latest?.completedAt &&
1019	        now - new Date(latest.completedAt).getTime() < staleAfterMs;
1020	      if (fresh && !input?.force) {
1021	        results[provider] = {
1022	          status: 'skipped',
1023	          reason: 'Provider history is inside the freshness window',
1024	          runId: latest.id,
1025	        };
1026	        continue;
1027	      }
1028	
1029	      const result =
1030	        provider === 'STRIPE'
1031	          ? await hydrateStripeAccountingHistory(ownerId)
1032	          : await hydrateQuickBooksAccountingHistory(ownerId);
1033	      results[provider] = {
1034	        status: 'hydrated',
1035	        runId: result.run?.id ?? null,
1036	      };
1037	    } catch (error) {
1038	      results[provider] = {
1039	        status: 'failed',
1040	        reason: error instanceof Error ? error.message : String(error),
1041	      };
1042	    }
1043	  }
1044	
1045	  await db.insert(schema.accountingAuditLogs).values(
1046	    buildAccountingAuditLog({
1047	      ownerType: 'HILO_PLATFORM',
1048	      ownerId,
1049	      action: 'accounting.provider_history.scheduled',
1050	      objectType: 'accounting_provider_sync_run',
1051	      metadata: {
1052	        providers,
1053	        staleAfterMs,
1054	        force: input?.force === true,
1055	        results,
1056	      },
1057	    }),
1058	  );
1059	
1060	  return { ownerId, results };
1061	}
