1069	export function buildAccountingReconciliationFindingsSnapshot({
1070	  schools,
1071	  billingRows,
1072	  stripeHistory,
1073	  quickBooksHistory,
1074	  ownerId = DEFAULT_HILO_PLATFORM_OWNER_ID,
1075	  checkedAt = new Date(),
1076	}: ReconciliationSnapshotInput): ReconciliationFindingInsert[] {
1077	  const findings: ReconciliationFindingInsert[] = [];
1078	  const customerRows = stripeHistory.filter(
1079	    (row) => row.providerObjectType === 'customer',
1080	  );
1081	  const subscriptionRows = stripeHistory.filter(
1082	    (row) => row.providerObjectType === 'subscription',
1083	  );
1084	  const stripeInvoices = stripeHistory.filter(
1085	    (row) => row.providerObjectType === 'invoice',
1086	  );
1087	  const qbTransactions = quickBooksHistory.filter((row) =>
1088	    ['invoice', 'sales_receipt', 'journal_entry', 'payment'].includes(
1089	      row.providerObjectType,
1090	    ),
1091	  );
1092	
1093	  const stripeCustomerBySchool = new Map<string, StripeHistory[]>();
1094	  for (const row of customerRows) {
1095	    const current = stripeCustomerBySchool.get(row.flightSchoolId) ?? [];
1096	    current.push(row);
1097	    stripeCustomerBySchool.set(row.flightSchoolId, current);
1098	  }
1099	  const schoolsByStripeCustomer = new Map<string, Set<string>>();
1100	  for (const row of customerRows) {
1101	    if (!row.customerId) continue;
1102	    const set =
1103	      schoolsByStripeCustomer.get(row.customerId) ?? new Set<string>();
1104	    set.add(row.flightSchoolId);
1105	    schoolsByStripeCustomer.set(row.customerId, set);
1106	  }
1107	
1108	  for (const school of schools) {
1109	    const customers = stripeCustomerBySchool.get(school.id) ?? [];
1110	    if (customers.length === 0) {
1111	      findings.push(
1112	        finding({
1113	          ownerType: 'HILO_PLATFORM',
1114	          ownerId,
1115	          flightSchoolId: school.id,
1116	          findingKey: `stripe.customer.missing:${school.id}`,
1117	          findingType: 'STRIPE_CUSTOMER_MISSING',
1118	          severity: 'ERROR',
1119	          status: 'OPEN',
1120	          sourceSystem: 'Stripe',
1121	          title: 'Missing Stripe customer',
1122	          description: `${school.name} does not have a hydrated Hilo Stripe customer history record.`,
1123	          recommendedResolution:
1124	            'Link or create the Stripe customer, then hydrate Stripe history.',
1125	          internalObjectId: school.id,
1126	          lastDetectedAt: checkedAt,
1127	        }),
1128	      );
1129	    }
1130	    if (customers.length > 1) {
1131	      findings.push(
1132	        finding({
1133	          ownerType: 'HILO_PLATFORM',
1134	          ownerId,
1135	          flightSchoolId: school.id,
1136	          findingKey: `stripe.customer.duplicate:${school.id}`,
1137	          findingType: 'STRIPE_CUSTOMER_DUPLICATE',
1138	          severity: 'ERROR',
1139	          status: 'OPEN',
1140	          sourceSystem: 'Stripe',
1141	          title: 'Duplicate Stripe customers',
1142	          description: `${school.name} has ${customers.length} Stripe customers mapped in accounting history.`,
1143	          recommendedResolution:
1144	            'Resolve customer mapping so exactly one Stripe customer represents this flight school.',
1145	          internalObjectId: school.id,
1146	          stripeObjectId: customers
1147	            .map((row) => row.providerObjectId)
1148	            .join(','),
1149	          lastDetectedAt: checkedAt,
1150	        }),
1151	      );
1152	    }
1153	  }
1154	
1155	  for (const [customerId, schoolIds] of schoolsByStripeCustomer) {
1156	    if (schoolIds.size <= 1) continue;
1157	    const firstSchoolId = [...schoolIds][0];
1158	    findings.push(
1159	      finding({
1160	        ownerType: 'HILO_PLATFORM',
1161	        ownerId,
1162	        flightSchoolId: firstSchoolId,
1163	        findingKey: `stripe.customer.multi_school:${customerId}`,
1164	        findingType: 'STRIPE_CUSTOMER_MULTI_SCHOOL',
1165	        severity: 'CRITICAL',
1166	        status: 'OPEN',
1167	        sourceSystem: 'mapping',
1168	        title: 'Stripe customer mapped to multiple schools',
1169	        description: `Stripe customer ${customerId} is associated with multiple flight schools.`,
1170	        recommendedResolution:
1171	          'Repair the Stripe customer mapping before creating or reconciling invoices.',
1172	        stripeObjectId: customerId,
1173	        lastDetectedAt: checkedAt,
1174	      }),
1175	    );
1176	  }
1177	
1178	  const stripeInvoiceById = new Map(
1179	    stripeInvoices.map((row) => [row.providerObjectId, row]),
1180	  );
1181	  const stripeInvoiceByInternal = new Map(
1182	    stripeInvoices
1183	      .filter((row) => row.linkedInternalObjectId)
1184	      .map((row) => [row.linkedInternalObjectId as string, row]),
1185	  );
1186	  const qbByStripe = new Map(
1187	    qbTransactions
1188	      .filter((row) => row.linkedStripeObjectId)
1189	      .map((row) => [row.linkedStripeObjectId as string, row]),
1190	  );
1191	  const qbByInternal = new Map(
1192	    qbTransactions
1193	      .filter((row) => row.linkedInternalObjectId)
1194	      .map((row) => [row.linkedInternalObjectId as string, row]),
1195	  );
1196	
1197	  for (const row of billingRows) {
1198	    const stripeInvoice =
1199	      (row.stripeInvoiceId
1200	        ? stripeInvoiceById.get(row.stripeInvoiceId)
1201	        : null) ?? stripeInvoiceByInternal.get(row.id);
1202	    if (row.status !== 'DRAFT' && row.totalAmountCents > 0 && !stripeInvoice) {
1203	      findings.push(
1204	        finding({
1205	          ownerType: 'HILO_PLATFORM',
1206	          ownerId,
1207	          flightSchoolId: row.subscriberId,
1208	          findingKey: `hilo.invoice.missing_stripe:${row.id}`,
1209	          findingType: 'HILO_INVOICE_MISSING_STRIPE',
1210	          severity: 'WARNING',
1211	          status: 'OPEN',
1212	          sourceSystem: 'Hilo',
1213	          title: 'Hilo billing row missing Stripe invoice',
1214	          description:
1215	            'This Hilo billing row has billable amount but no hydrated Stripe invoice.',
1216	          recommendedResolution:
1217	            'Create or link the Stripe invoice, then hydrate Stripe history.',
1218	          billingReportRowId: row.id,
1219	          internalObjectId: row.id,
1220	          lastDetectedAt: checkedAt,
1221	        }),
1222	      );
1223	    }
1224	    if (stripeInvoice) {
1225	      const amountVariance =
1226	        (stripeInvoice.amountCents ?? 0) - row.totalAmountCents;
1227	      const taxVariance =
1228	        (stripeInvoice.taxAmountCents ?? 0) - row.taxAmountCents;
1229	      if (amountVariance !== 0 || taxVariance !== 0) {
1230	        findings.push(
1231	          finding({
1232	            ownerType: 'HILO_PLATFORM',
1233	            ownerId,
1234	            flightSchoolId: row.subscriberId,
1235	            findingKey: `stripe.invoice.variance:${stripeInvoice.providerObjectId}`,
