42	export async function queueQuickBooksStudentInvoiceSync(input: {
43	  flightSchoolId: string;
44	  invoiceId: string;
45	  status?: string | null;
46	  balanceImpactCents?: number | null;
47	}): Promise<QuickBooksAutoSyncQueueResult> {
48	  if (!shouldAutoSyncQuickBooksInvoice(input.status)) {
49	    return { queued: false, reason: 'not_ready' };
50	  }
51	
52	  try {
53	    const connection = await qbConnectionRepo.findActive(input.flightSchoolId);
54	    const isCredit = (input.balanceImpactCents ?? 0) > 0;
55	    await enqueueQBSync({
56	      realmId: connection.realmId,
57	      flightSchoolId: input.flightSchoolId,
58	      entityType: isCredit ? 'CreditMemo' : 'Invoice',
59	      entityId: input.invoiceId,
60	      operation: 'create',
61	      atosEntityId: input.invoiceId,
62	    });
63	    return { queued: true };
64	  } catch (error) {
65	    const message = error instanceof Error ? error.message : String(error);
66	    if (/quickbooks.*not connected|not connected/i.test(message)) {
67	      return { queued: false, reason: 'not_connected' };
68	    }
69	    console.warn('[QuickBooks] Invoice auto-sync enqueue failed:', message);
70	    return { queued: false, reason: 'failed' };
71	  }
72	}
