129	    return 'Add this QuickBooks realm/company to QB_PAYROLL_DIRECT_WRITE_REALM_ALLOWLIST only after provider write approval and finance signoff.';
130	  }
131	  if (status === 'WRITE_EXCHANGE_BLOCKED_BY_PROVIDER_CAPABILITY') {
132	    return 'Confirm QuickBooks Payroll/Workforce API access for this realm and rerun the payroll capability check.';
133	  }
134	  if (status === 'WRITE_EXCHANGE_NOT_IMPLEMENTED') {
135	    return 'Direct Payroll API writes require a dedicated provider exchange implementation. Journal-entry fallback may be used when available.';
136	  }
137	  if (status === 'WRITE_EXCHANGE_DISABLED') {
138	    return 'Set QB_PAYROLL_DIRECT_WRITE_EXCHANGE_ENABLED=true only after the dedicated direct Payroll exchange implementation is deployed and approved.';
139	  }
140	  if (status === 'WRITE_EXCHANGE_AVAILABLE') {
141	    return 'Direct Payroll API write exchange is implemented, enabled, scoped, and allowed for this realm.';
142	  }
143	  return 'Readiness checks passed, but write permission must still be evaluated separately.';
144	}
