146	export function evaluateDirectPayrollWriteExchange(input: {
147	  configEnabled: boolean;
148	  capabilityConfirmed: boolean;
149	  providerSupported: boolean;
150	  readinessStatus: string;
151	  providerAccountId: string;
152	  requiredScopes: string[];
153	  missingScopeGroups: string[];
154	  implemented?: boolean;
155	  enabledByConfig?: boolean;
156	  realmAllowlist?: string[];
157	}): DirectPayrollWriteExchangeState {
158	  const implemented =
159	    input.implemented ?? DIRECT_PAYROLL_WRITE_EXCHANGE_IMPLEMENTED;
160	  const enabledByConfig =
161	    input.enabledByConfig ?? directPayrollWriteExchangeEnabled();
162	  const allowlist = input.realmAllowlist ?? configuredRealmAllowlist();
163	  const allowedForRealm =
164	    input.providerAccountId !== 'quickbooks-unconnected' &&
165	    allowlist.length > 0 &&
166	    allowlist.includes(input.providerAccountId);
167	  const realmAllowmentStatus =
168	    input.providerAccountId === 'quickbooks-unconnected' ||
169	    allowlist.length === 0
170	      ? ('not_configured' as const)
171	      : allowedForRealm
172	        ? ('allowed' as const)
173	        : ('not_allowed' as const);
174	  const readinessConfirmed =
175	    input.configEnabled &&
176	    input.capabilityConfirmed &&
177	    input.providerSupported &&
178	    input.readinessStatus === 'SUPPORTED' &&
179	    input.missingScopeGroups.length === 0;
180	
181	  let status: DirectPayrollWriteExchangeStatus = 'READINESS_CONFIRMED';
182	  if (!input.configEnabled || !input.capabilityConfirmed) {
183	    status = 'WRITE_EXCHANGE_BLOCKED_BY_CONFIG';
184	  } else if (input.missingScopeGroups.length > 0) {
185	    status = 'WRITE_EXCHANGE_BLOCKED_BY_SCOPE';
186	  } else if (!readinessConfirmed) {
187	    status = 'WRITE_EXCHANGE_BLOCKED_BY_PROVIDER_CAPABILITY';
188	  } else if (!implemented) {
189	    status = 'WRITE_EXCHANGE_NOT_IMPLEMENTED';
190	  } else if (!enabledByConfig) {
191	    status = 'WRITE_EXCHANGE_DISABLED';
192	  } else if (!allowedForRealm) {
193	    status = 'WRITE_EXCHANGE_BLOCKED_BY_REALM';
194	  } else {
195	    status = 'WRITE_EXCHANGE_AVAILABLE';
196	  }
197	
198	  const operation = DIRECT_PAYROLL_EXCHANGE_OPERATIONS[0];
199	  return {
200	    readinessLabel: readinessConfirmed
201	      ? 'Readiness confirmed'
202	      : 'Readiness unavailable',
203	    status,
204	    implemented,
205	    enabledByConfig,
206	    allowedForRealm,
207	    realmAllowmentStatus,
208	    realmAllowlist: allowlist,
209	    providerAccountId: input.providerAccountId,
210	    requiredScopes: input.requiredScopes,
211	    missingScopeGroups: input.missingScopeGroups,
212	    requiredSourceData: [...operation.requiredSourceData],
213	    requiredMappings: [...operation.requiredMappings],
214	    idempotencyRequired: true,
215	    dryRunSupported: operation.supportsDryRun,
216	    recommendedAction: recommendedAction(status),
217	  };
218	}
219	
220	export function assertDirectPayrollExchangeWritable(
221	  state: DirectPayrollWriteExchangeState,
222	): void {
223	  if (state.status === 'WRITE_EXCHANGE_AVAILABLE') return;
224	  if (state.status === 'WRITE_EXCHANGE_NOT_IMPLEMENTED') {
225	    throw new DirectPayrollExchangeError(
226	      'DirectPayrollWriteAdapterNotImplemented',
227	      'QuickBooks Payroll readiness checks passed, but direct Payroll API write exchange is not implemented.',
228	      state.recommendedAction,
229	    );
230	  }
231	  if (state.status === 'WRITE_EXCHANGE_DISABLED') {
232	    throw new DirectPayrollExchangeError(
233	      'DirectPayrollWriteDisabled',
234	      'Direct QuickBooks Payroll API write exchange is disabled by configuration.',
235	      state.recommendedAction,
236	    );
237	  }
238	  if (state.status === 'WRITE_EXCHANGE_BLOCKED_BY_CONFIG') {
239	    throw new DirectPayrollExchangeError(
240	      'PayrollProviderCapabilityUnavailable',
241	      'Direct QuickBooks Payroll API write exchange is blocked by configuration.',
242	      state.recommendedAction,
243	    );
244	  }
245	  if (state.status === 'WRITE_EXCHANGE_BLOCKED_BY_SCOPE') {
246	    throw new DirectPayrollExchangeError(
247	      'PayrollWriteScopeMissing',
248	      'Direct QuickBooks Payroll API write exchange is blocked by missing payroll write scope readiness.',
249	      state.recommendedAction,
250	    );
251	  }
252	  if (state.status === 'WRITE_EXCHANGE_BLOCKED_BY_REALM') {
253	    throw new DirectPayrollExchangeError(
254	      'PayrollRealmNotAllowed',
255	      'Direct QuickBooks Payroll API write exchange is blocked because this realm is not explicitly allowed.',
256	      state.recommendedAction,
257	    );
258	  }
259	  if (state.status === 'WRITE_EXCHANGE_BLOCKED_BY_PROVIDER_CAPABILITY') {
260	    throw new DirectPayrollExchangeError(
261	      'PayrollProviderCapabilityUnavailable',
262	      'Direct QuickBooks Payroll API write exchange is blocked by provider capability.',
263	      state.recommendedAction,
264	    );
265	  }
266	  throw new DirectPayrollExchangeError(
267	    'PayrollSourceDataIncomplete',
268	    'Direct QuickBooks Payroll API write exchange requires complete payroll source data before writes are allowed.',
269	    state.recommendedAction,
270	  );
271	}
272	
273	export async function executeDirectPayrollExchange(input: {
274	  state: DirectPayrollWriteExchangeState;
275	  operationName: (typeof DIRECT_PAYROLL_EXCHANGE_OPERATIONS)[number]['operationName'];
276	  idempotencyKey: string;
277	  dryRun?: boolean;
278	}): Promise<never> {
279	  const operation = DIRECT_PAYROLL_EXCHANGE_OPERATIONS.find(
280	    (item) => item.operationName === input.operationName,
281	  );
282	  if (!operation) {
283	    throw new DirectPayrollExchangeError(
284	      'PayrollWriteUnsupportedOperation',
285	      `Direct payroll operation ${input.operationName} is not supported by this adapter boundary.`,
286	      'Use one of the explicitly supported direct payroll exchange operation names.',
287	    );
288	  }
289	  if (!input.idempotencyKey.trim()) {
290	    throw new DirectPayrollExchangeError(
291	      'PayrollSourceDataIncomplete',
292	      'Direct payroll exchange requires an idempotency key before any provider write.',
293	      'Generate an owner-scoped idempotency key for the payroll period before retrying.',
294	    );
295	  }
296	  assertDirectPayrollExchangeWritable(input.state);
297	  throw new DirectPayrollExchangeError(
298	    'DirectPayrollExchangeNotImplemented',
299	    `Direct payroll operation ${input.operationName} has no provider adapter in this build.`,
300	    'Deploy a dedicated QuickBooks Payroll/Workforce write adapter before enabling direct payroll writes.',
301	  );
302	}
