186	function stableStringify(value: unknown): string {
187	  if (Array.isArray(value)) {
188	    return `[${value.map((item) => stableStringify(item)).join(',')}]`;
189	  }
190	  if (value && typeof value === 'object') {
191	    return `{${Object.entries(value as Record<string, unknown>)
192	      .sort(([a], [b]) => a.localeCompare(b))
193	      .map(([key, item]) => `${JSON.stringify(key)}:${stableStringify(item)}`)
194	      .join(',')}}`;
195	  }
196	  return JSON.stringify(value);
197	}
