216	export function calculatePayrollSourceTotals(
217	  lines: NormalizedPayrollSourceLine[],
218	): PayrollSourceTotals {
219	  return lines.reduce<PayrollSourceTotals>(
220	    (totals, line) => {
221	      if (line.sourceLineType === 'gross_wages') {
222	        totals.grossWagesCents += line.amountCents;
223	      }
224	      if (line.sourceLineType === 'earning_regular') {
225	        totals.regularWagesCents += line.amountCents;
226	      }
227	      if (line.sourceLineType === 'earning_overtime') {
228	        totals.overtimeWagesCents += line.amountCents;
229	      }
230	      if (line.sourceLineType === 'earning_other') {
231	        totals.otherEarningsCents += line.amountCents;
232	      }
233	      if (line.sourceLineType === 'employer_tax') {
234	        totals.employerTaxesCents +=
235	          line.employerTaxAmountCents ?? line.amountCents;
236	      }
237	      if (line.sourceLineType === 'employee_withholding') {
238	        totals.employeeWithholdingsCents +=
239	          line.employeeWithholdingAmountCents ?? line.amountCents;
240	      }
241	      if (line.sourceLineType === 'benefit_deduction') {
242	        totals.employeeBenefitsDeductionsCents +=
243	          line.employeeAmountCents ?? line.amountCents;
244	        totals.employerBenefitsDeductionsCents += line.employerAmountCents ?? 0;
245	      }
246	      if (line.sourceLineType === 'payment_clearing') {
247	        totals.paymentClearingCents += line.amountCents;
248	        totals.netPayCents += line.netPayCents ?? line.amountCents;
249	      }
250	      return totals;
251	    },
252	    { ...EMPTY_PAYROLL_SOURCE_TOTALS },
253	  );
254	}
