272	export function validatePayrollSourceRun(
273	  run: NormalizedPayrollSourceRun,
274	  options: { syncMode?: PayrollSourceSyncMode } = {},
275	): PayrollSourceValidationResult {
276	  const syncMode = options.syncMode ?? 'gross_fallback';
277	  const findings: PayrollSourceValidationFinding[] = [];
278	  const sourceLineTypes = lineTypeSet(run.lines);
279	  const calculated = calculatePayrollSourceTotals(run.lines);
280	  const earningGross =
281	    calculated.regularWagesCents +
282	    calculated.overtimeWagesCents +
283	    calculated.otherEarningsCents;
284	  const authoritativeGross =
285	    calculated.grossWagesCents > 0 ? calculated.grossWagesCents : earningGross;
286	  const fullMissingSeverity =
287	    syncMode === 'gross_fallback' ? ('WARNING' as const) : ('ERROR' as const);
288	
289	  if (run.payrollPeriodEnd < run.payrollPeriodStart) {
290	    findings.push(
291	      finding({
292	        findingKey: 'payroll_source.period_invalid',
293	        findingType: 'PAYROLL_SOURCE_PERIOD_INVALID',
294	        severity: 'ERROR',
295	        title: 'Payroll period is invalid',
296	        description: 'Payroll period end is before payroll period start.',
297	        recommendedResolution:
298	          'Correct the ATOS payroll period before importing or syncing payroll.',
299	      }),
300	    );
301	  }
302	
303	  if (!run.atosPayrollRunId.trim()) {
304	    findings.push(
305	      finding({
306	        findingKey: 'payroll_source.run_id_missing',
307	        findingType: 'PAYROLL_SOURCE_RUN_ID_MISSING',
308	        severity: 'ERROR',
309	        title: 'ATOS payroll run ID is missing',
310	        description: 'Source payroll runs require a stable ATOS run ID.',
311	        recommendedResolution:
312	          'Provide a stable ATOS payroll run ID before importing payroll source data.',
313	      }),
314	    );
315	  }
316	
317	  const seenLineKeys = new Set<string>();
318	  for (const line of run.lines) {
319	    if (!line.sourceLineId.trim()) {
320	      findings.push(
321	        finding({
322	          findingKey: `payroll_source.line_id_missing:${seenLineKeys.size}`,
323	          findingType: 'PAYROLL_SOURCE_LINE_ID_MISSING',
324	          severity: 'ERROR',
325	          title: 'Payroll source line ID is missing',
326	          description:
327	            'Every payroll source line needs a stable source line ID for idempotency.',
328	          recommendedResolution:
329	            'Send stable source line IDs from ATOS for every payroll detail line.',
330	          sourceLineId: line.sourceLineId || null,
331	        }),
332	      );
333	    }
334	    const lineKey = `${line.sourceLineType}:${line.sourceLineId}`;
335	    if (seenLineKeys.has(lineKey)) {
336	      findings.push(
337	        finding({
338	          findingKey: `payroll_source.line_duplicate:${lineKey}`,
339	          findingType: 'PAYROLL_SOURCE_LINE_DUPLICATE',
340	          severity: 'ERROR',
341	          title: 'Duplicate payroll source line',
342	          description:
343	            'A payroll source line type/source line ID pair appears more than once.',
344	          recommendedResolution:
345	            'Deduplicate the source payload or send unique source line IDs.',
346	          sourceLineId: line.sourceLineId,
347	        }),
348	      );
349	    }
350	    seenLineKeys.add(lineKey);
351	    if (line.currency !== run.currency) {
352	      findings.push(
353	        finding({
354	          findingKey: `payroll_source.currency_mismatch:${lineKey}`,
355	          findingType: 'PAYROLL_SOURCE_CURRENCY_MISMATCH',
356	          severity: 'ERROR',
357	          title: 'Payroll source currency mismatch',
358	          description: `Line ${line.sourceLineId} uses ${line.currency}; the run currency is ${run.currency}.`,
359	          recommendedResolution:
360	            'Split payroll into separate currency-specific runs or normalize currency before import.',
361	          sourceLineId: line.sourceLineId,
362	        }),
363	      );
364	    }
365	    const percentageTotal = (line.allocations ?? []).reduce(
366	      (sum, allocation) => sum + (allocation.allocationPercentage ?? 0),
367	      0,
368	    );
369	    if (
370	      (line.allocations?.length ?? 0) > 0 &&
371	      Math.abs(percentageTotal - 100) > 0.01
372	    ) {
373	      findings.push(
374	        finding({
375	          findingKey: `payroll_source.allocation_percentage_invalid:${lineKey}`,
376	          findingType: 'PAYROLL_SOURCE_ALLOCATION_PERCENTAGE_INVALID',
377	          severity: 'ERROR',
378	          title: 'Payroll allocation percentage is invalid',
379	          description: `Allocations for source line ${line.sourceLineId} total ${percentageTotal.toFixed(4)}%, not 100%.`,
380	          recommendedResolution:
381	            'Correct ATOS allocation percentages so every allocatable payroll source line totals 100%.',
382	          sourceLineId: line.sourceLineId,
383	        }),
384	      );
385	    }
386	  }
387	
388	  if (authoritativeGross <= 0) {
389	    findings.push(
390	      finding({
391	        findingKey: 'payroll_source.gross_wages_missing',
392	        findingType: 'PAYROLL_SOURCE_GROSS_WAGES_MISSING',
393	        severity: 'ERROR',
394	        title: 'Gross wages are missing',
395	        description:
396	          'Payroll source data must include positive gross wage or earning lines.',
397	        recommendedResolution:
398	          'Import ATOS gross wage or earning lines before payroll sync.',
399	      }),
400	    );
401	  }
402	
403	  if (
404	    calculated.grossWagesCents > 0 &&
405	    earningGross > 0 &&
406	    calculated.grossWagesCents !== earningGross
407	  ) {
408	    findings.push(
409	      finding({
410	        findingKey: 'payroll_source.gross_earnings_variance',
411	        findingType: 'PAYROLL_SOURCE_GROSS_EARNINGS_VARIANCE',
412	        severity: 'ERROR',
413	        title: 'Gross wages do not match earnings',
414	        description: `Gross wage lines total ${calculated.grossWagesCents}; earning detail lines total ${earningGross}.`,
415	        recommendedResolution:
416	          'Correct ATOS earning lines or gross wage totals before full payroll sync.',
417	      }),
418	    );
419	  }
420	
421	  if (
422	    run.totals.grossWagesCents > 0 &&
423	    authoritativeGross > 0 &&
424	    run.totals.grossWagesCents !== authoritativeGross
425	  ) {
426	    findings.push(
427	      finding({
428	        findingKey: 'payroll_source.run_gross_total_variance',
429	        findingType: 'PAYROLL_SOURCE_RUN_GROSS_TOTAL_VARIANCE',
430	        severity: 'ERROR',
431	        title: 'Payroll run gross total does not match source lines',
432	        description: `Run gross total is ${run.totals.grossWagesCents}; source lines total ${authoritativeGross}.`,
433	        recommendedResolution:
434	          'Regenerate ATOS payroll source totals from source lines before syncing.',
435	      }),
436	    );
437	  }
438	
439	  const availableDimensions: string[] = PAYROLL_FULL_SOURCE_DIMENSIONS.filter(
440	    (dimension) =>
441	      dimension.lineTypes.some((lineType) => sourceLineTypes.has(lineType)),
442	  ).map((dimension) => dimension.key);
443	  if (hasAllocationData(run.lines)) {
444	    availableDimensions.push(PAYROLL_ALLOCATION_SOURCE_DIMENSION.key);
445	  }
446	
447	  const missingDimensions: string[] = PAYROLL_FULL_SOURCE_DIMENSIONS.filter(
448	    (dimension) => !availableDimensions.includes(dimension.key),
449	  ).map((dimension) => dimension.key);
450	  if (!availableDimensions.includes(PAYROLL_ALLOCATION_SOURCE_DIMENSION.key)) {
451	    missingDimensions.push(PAYROLL_ALLOCATION_SOURCE_DIMENSION.key);
452	  }
453	
454	  for (const dimension of PAYROLL_FULL_SOURCE_DIMENSIONS) {
455	    if (availableDimensions.includes(dimension.key)) continue;
456	    findings.push(
457	      finding({
458	        findingKey: `payroll_source.dimension_missing:${dimension.key}`,
459	        findingType: 'PAYROLL_SOURCE_DIMENSION_MISSING',
460	        severity: fullMissingSeverity,
461	        title: `${dimension.label} missing`,
462	        description: `${dimension.requiredSourceData} is not present in this payroll source run.`,
463	        recommendedResolution:
464	          'Add this authoritative ATOS source dimension before enabling full payroll sync.',
465	        metadata: { dimensionKey: dimension.key, syncMode },
466	      }),
467	    );
468	  }
469	
470	  if (!availableDimensions.includes(PAYROLL_ALLOCATION_SOURCE_DIMENSION.key)) {
471	    findings.push(
472	      finding({
473	        findingKey: `payroll_source.dimension_missing:${PAYROLL_ALLOCATION_SOURCE_DIMENSION.key}`,
474	        findingType: 'PAYROLL_SOURCE_DIMENSION_MISSING',
475	        severity: fullMissingSeverity,
476	        title: `${PAYROLL_ALLOCATION_SOURCE_DIMENSION.label} missing`,
477	        description: `${PAYROLL_ALLOCATION_SOURCE_DIMENSION.requiredSourceData} is not present in this payroll source run.`,
478	        recommendedResolution:
479	          'Add source-backed department, class, or location allocations before enabling allocation-aware full payroll sync.',
480	        metadata: {
481	          dimensionKey: PAYROLL_ALLOCATION_SOURCE_DIMENSION.key,
482	          syncMode,
483	        },
484	      }),
485	    );
486	  }
487	
488	  if (sourceLineTypes.has('payment_clearing')) {
489	    const expectedNetPay =
490	      authoritativeGross -
491	      calculated.employeeWithholdingsCents -
492	      calculated.employeeBenefitsDeductionsCents;
493	    if (
494	      calculated.paymentClearingCents > 0 &&
495	      calculated.paymentClearingCents !== expectedNetPay
496	    ) {
497	      findings.push(
498	        finding({
499	          findingKey: 'payroll_source.net_pay_variance',
500	          findingType: 'PAYROLL_SOURCE_NET_PAY_VARIANCE',
501	          severity: 'ERROR',
502	          title: 'Payroll payment clearing does not reconcile',
503	          description: `Payment clearing totals ${calculated.paymentClearingCents}; expected net pay is ${expectedNetPay}.`,
504	          recommendedResolution:
505	            'Correct ATOS net pay/payment clearing lines before posting a full payroll journal entry.',
506	        }),
507	      );
508	    }
509	  }
510	
511	  const hasErrors = findings.some((item) => item.severity === 'ERROR');
512	  const sourceReadyForGrossFallback = authoritativeGross > 0 && !hasErrors;
513	  const sourceReadyForFullPayrollSync =
514	    sourceReadyForGrossFallback && missingDimensions.length === 0;
515	  const status: PayrollSourceValidationResult['status'] = hasErrors
516	    ? 'source_validation_failed'
517	    : sourceReadyForFullPayrollSync
518	      ? 'source_ready_for_full_payroll_sync'
519	      : sourceReadyForGrossFallback
520	        ? 'source_ready_for_gross_fallback'
521	        : 'source_data_incomplete';
522	
523	  return {
524	    status,
525	    sourceReadyForGrossFallback,
526	    sourceReadyForFullPayrollSync,
527	    availableDimensions,
528	    missingDimensions,
529	    findings,
530	  };
531	}
