533	export function buildNormalizedPayrollSourceRun(
534	  input: Omit<
535	    NormalizedPayrollSourceRun,
536	    'sourceHash' | 'totals' | 'status'
537	  > & {
538	    totals?: Partial<PayrollSourceTotals>;
539	    status?: PayrollSourceRunStatus;
540	  },
541	): NormalizedPayrollSourceRun {
542	  const calculatedTotals = calculatePayrollSourceTotals(input.lines);
543	  const totals: PayrollSourceTotals = {
544	    ...calculatedTotals,
545	    ...input.totals,
546	  };
547	  const hashInput = {
548	    atosPayrollRunId: input.atosPayrollRunId,
549	    flightSchoolId: input.flightSchoolId,
550	    payrollPeriodStart: input.payrollPeriodStart.toISOString(),
551	    payrollPeriodEnd: input.payrollPeriodEnd.toISOString(),
552	    payDate: input.payDate?.toISOString() ?? null,
553	    sourceSystem: input.sourceSystem,
554	    sourceVersion: input.sourceVersion,
555	    currency: input.currency,
556	    totals,
557	    lines: input.lines.map((line) => ({
558	      ...line,
559	      effectiveStart: line.effectiveStart?.toISOString() ?? null,
560	      effectiveEnd: line.effectiveEnd?.toISOString() ?? null,
561	      paymentDate: line.paymentDate?.toISOString() ?? null,
562	    })),
563	  };
564	  return {
565	    ...input,
566	    totals,
567	    status: input.status ?? 'imported',
568	    sourceHash: buildPayrollSourceHash(hashInput),
569	  };
570	}
