311	export function buildPlatformAccountingBlockers({
312	  readinessBlockers = [],
313	  billingRows = [],
314	  exceptions = [],
315	  reconciliationFindings = [],
316	  auditEvents = [],
317	  checkedAt = new Date(),
318	}: BuildPlatformAccountingBlockersInput): AccountingBlockerDetail[] {
319	  const checked = iso(checkedAt);
320	  const blockers: AccountingBlockerDetail[] = [];
321	
322	  for (const blocker of readinessBlockers) {
323	    blockers.push({
324	      id: `readiness:${blocker.key}`,
325	      title: blocker.key.replace(/[_\.]/g, ' '),
326	      affectedEntity: blocker.key,
327	      severity: severity(blocker.severity),
328	      sourceSystem: sourceForReadinessKey(blocker.key),
329	      description: blocker.message,
330	      whyItMatters:
331	        'Platform accounting can produce incomplete invoices, tax reports, or ledger syncs while this check is failing.',
332	      recommendedResolution:
333	        'Complete the required configuration, mapping, or finance approval, then recheck accounting readiness.',
334	      actions: [
335	        readinessAction(blocker.key),
336	        { label: 'Recheck status', type: 'refresh' },
337	      ],
338	      lastCheckedAt: checked,
339	      status: 'Blocked',
340	      relatedEventLogs: [],
341	    });
342	  }
343	
344	  for (const finding of reconciliationFindings) {
345	    if (finding.status === 'RESOLVED') continue;
346	    blockers.push({
347	      id: `reconciliation:${finding.id}`,
348	      title: finding.title,
349	      affectedEntity:
350	        finding.flightSchoolName ??
351	        finding.stripeObjectId ??
352	        finding.quickbooksObjectId ??
353	        finding.internalObjectId ??
354	        finding.flightSchoolId,
355	      severity: severity(finding.severity),
356	      sourceSystem: sourceFromFinding(finding.sourceSystem),
357	      description: finding.description,
358	      whyItMatters:
359	        'Cross-system accounting history is not reconciled, so invoices, tax totals, or ledger status may be stale or incomplete.',
360	      recommendedResolution: finding.recommendedResolution,
361	      actions: actionsForFinding(finding),
362	      lastCheckedAt: iso(finding.lastDetectedAt ?? checked),
363	      status: statusFromFinding(finding),
364	      relatedEventLogs: relatedEvents(auditEvents, [
365	        finding.id,
366	        finding.internalObjectId,
367	        finding.stripeObjectId,
368	        finding.quickbooksObjectId,
369	      ]),
370	    });
371	  }
372	
373	  for (const row of billingRows) {
374	    if (
375	      row.statusReasons.length === 0 &&
376	      row.accountingStatus !== 'Needs mapping'
377	    ) {
378	      continue;
379	    }
380	    const missingStripe = !row.stripeCustomerId;
381	    const missingPoe = !row.hasMonthlyPoePeak;
382	    const title = missingStripe
383	      ? 'Missing Stripe customer'
384	      : missingPoe
385	        ? 'Missing monthly POE peak'
386	        : 'Billing row needs review';
387	    blockers.push({
388	      id: `billing-row:${row.subscriberId}:${title.toLowerCase().replace(/\s+/g, '-')}`,
389	      title,
390	      affectedEntity: row.flightSchoolName,
391	      severity: missingStripe ? 'error' : 'warning',
392	      sourceSystem: missingStripe ? 'Stripe' : 'Hilo',
393	      description: row.statusReasons.join(' '),
394	      whyItMatters: missingStripe
395	        ? 'Stripe invoice delivery and collection cannot be verified for this flight school.'
396	        : 'POE-based billing can be understated or stale when the monthly peak is missing.',
397	      recommendedResolution: missingStripe
398	        ? 'Link or create the Hilo Stripe customer for this flight school before sending invoices.'
399	        : 'Run or verify the POE billing job for the period, then recheck the billing row.',
400	      actions: [
401	        {
402	          label: missingStripe ? 'Link customer' : 'Review POE history',
403	          type: 'navigate',
404	          href: missingStripe
405	            ? `/super-admin/billing/${row.subscriberId}`
406	            : `/super-admin/billing/${row.subscriberId}?tab=poe-history`,
407	        },
408	        { label: 'Recheck status', type: 'refresh' },
409	      ],
410	      lastCheckedAt: checked,
411	      status: statusFromWorkflow(row.accountingStatus),
412	      relatedEventLogs: relatedEvents(auditEvents, [
413	        row.id,
414	        row.subscriberId,
415	        row.stripeInvoiceId,
416	        row.quickbooksInvoiceId,
417	      ]),
418	    });
419	  }
420	
421	  for (const exception of exceptions) {
422	    if (exception.resolutionStatus === 'RESOLVED') continue;
423	    const provider = exception.provider.toUpperCase();
424	    blockers.push({
425	      id: `exception:${exception.id}`,
426	      title: exception.errorCode ?? `${exception.objectType} exception`,
427	      affectedEntity:
428	        exception.externalObjectId ??
429	        exception.internalObjectId ??
430	        exception.objectType,
431	      severity: severity(exception.severity),
432	      sourceSystem:
433	        provider === 'STRIPE'
434	          ? 'Stripe'
435	          : provider === 'QUICKBOOKS'
436	            ? 'QuickBooks'
437	            : 'Hilo',
438	      description: exception.errorMessage,
439	      whyItMatters:
440	        'Open accounting exceptions indicate a record has not reconciled cleanly across the billing/accounting workflow.',
441	      recommendedResolution:
442	        'Review the exception, resolve the underlying data or mapping issue, then mark the exception resolved.',
443	      actions: [
444	        {
445	          label: 'Resolve exception',
446	          type: 'resolve',
447	          endpoint: `/accounting/exceptions/${exception.id}/resolve?ownerType=HILO_PLATFORM&ownerId=hilo-platform`,
448	          method: 'POST',
449	        },
450	        { label: 'Recheck status', type: 'refresh' },
451	      ],
452	      lastCheckedAt: checked,
453	      status: 'Manual action required',
454	      relatedEventLogs: relatedEvents(auditEvents, [
455	        exception.id,
456	        exception.internalObjectId,
457	        exception.externalObjectId,
458	      ]),
459	    });
460	  }
461	
462	  return blockers;
463	}
