371	export function resolveQuickBooksPayrollCapabilityStatus(input: {
372	  configEnabled: boolean;
373	  capabilityConfirmed: boolean;
374	  connectionPresent: boolean;
375	  missingScopeGroups: string[];
376	  providerReadFailure?: string | null;
377	}): PayrollCapabilityStatus {
378	  if (!input.configEnabled) return 'DISABLED_BY_CONFIG';
379	  if (!input.capabilityConfirmed) return 'UNCONFIRMED_BY_CONFIG';
380	  if (!input.connectionPresent) return 'CONNECTION_MISSING';
381	  if (input.missingScopeGroups.length > 0) return 'MISSING_SCOPES';
382	  if (input.providerReadFailure) return 'PROVIDER_READ_FAILED';
383	  return 'SUPPORTED';
384	}
