386	function directPayrollRecommendedAction(status: PayrollCapabilityStatus) {
387	  if (status === 'DISABLED_BY_CONFIG') {
388	    return 'Enable QB_PAYROLL_API_SYNC_ENABLED only after Intuit Payroll/Workforce API access is approved.';
389	  }
390	  if (status === 'UNCONFIRMED_BY_CONFIG') {
391	    return 'Confirm Intuit Payroll/Workforce API access, production availability, and scope approval, then set QB_PAYROLL_API_CAPABILITY_CONFIRMED=true.';
392	  }
393	  if (status === 'CONNECTION_MISSING') {
394	    return 'Reconnect the flight school QuickBooks company before checking payroll capability.';
395	  }
396	  if (status === 'MISSING_SCOPES') {
397	    return 'Reauthorize QuickBooks with payroll.compensation.read or the approved legacy QuickBooks Payroll scope.';
398	  }
399	  if (status === 'PROVIDER_READ_FAILED') {
400	    return 'Refresh or reconnect QuickBooks, then recheck Payroll API capability.';
401	  }
402	  if (status === 'SUPPORTED') {
403	    return 'Direct Payroll API capability is configured and read checks passed. Direct write exchange still remains guarded by the payroll sync implementation.';
404	  }
405	  return 'Run a payroll capability recheck.';
406	}
