10	function readArg(prefix: string): string | undefined {
11	  const match = process.argv.slice(2).find((arg) => arg.startsWith(prefix));
12	  return match?.slice(prefix.length);
13	}
14	
15	function outputFormat() {
16	  return readArg('--format=') === 'csv' ? 'csv' : 'json';
17	}
18	
19	function csvEscape(value: unknown): string {
20	  const text =
21	    typeof value === 'string' ? value : JSON.stringify(value ?? '') ?? '';
22	  return `"${text.replace(/"/g, '""')}"`;
23	}
24	
25	function reportToCsv(report: AccountingBackfillDryRunReport): string {
26	  const rows: Array<Record<string, unknown>> = [];
27	  const envelope = report as unknown as Record<string, unknown>;
28	  if (envelope.environment) {
29	    rows.push({ section: 'environment', record: envelope.environment });
30	  }
31	  const pushRecords = (section: string, records: unknown[]) => {
32	    for (const record of records) rows.push({ section, record });
33	  };
34	
35	  pushRecords('unmappedStripeCustomers', report.unmappedStripeCustomers);
36	  pushRecords('unmappedStripeInvoices', report.unmappedStripeInvoices);
37	  pushRecords('unmappedStripePaymentObjects', report.unmappedStripePaymentObjects);
38	  pushRecords('unmappedQuickBooksEntities', report.unmappedQuickBooksEntities);
39	  pushRecords(
40	    'legacyUserScopedQuickBooksIntegrations',
41	    report.legacyUserScopedQuickBooksIntegrations,
42	  );
43	  pushRecords(
44	    'recordsRequiringOwnerAssignment',
45	    report.recordsRequiringOwnerAssignment,
46	  );
47	  pushRecords('recordsUnsafeToAutoMigrate', report.recordsUnsafeToAutoMigrate);
48	  pushRecords(
49	    'recommendedAutomaticMigrations',
50	    report.recommendedAutomaticMigrations,
51	  );
52	  for (const group of report.duplicateLegacyMappings) {
53	    rows.push({
54	      section: 'duplicateLegacyMappings',
55	      key: group.key,
56	      record: group.records,
57	    });
58	  }
59	  for (const item of report.requiredManualReviewItems) {
60	    rows.push({
61	      section: 'requiredManualReviewItems',
62	      reason: item.reason,
63	      record: item.record,
64	    });
65	  }
66	
67	  const header = ['section', 'reason', 'key', 'record'];
68	  return [
69	    header.join(','),
70	    ...rows.map((row) => header.map((key) => csvEscape(row[key])).join(',')),
71	  ].join('\n');
72	}
73	
74	function emitReport(report: AccountingBackfillDryRunReport | Record<string, unknown>) {
75	  const body =
76	    outputFormat() === 'csv'
77	      ? reportToCsv(report as AccountingBackfillDryRunReport)
78	      : JSON.stringify(report, null, 2);
79	  const outPath = readArg('--out=');
80	  if (outPath) {
81	    writeFileSync(outPath, `${body}\n`);
82	    return;
83	  }
84	  console.log(body);
85	}
86	
87	function extractRealmId(...values: unknown[]) {
88	  for (const value of values) {
89	    if (!value || typeof value !== 'object') continue;
90	    const data = value as Record<string, unknown>;
91	    const realmId =
92	      data.realmId ?? data.realm_id ?? data.realmID ?? data.intuitRealmId;
93	    if (typeof realmId === 'string' && realmId.trim()) return realmId.trim();
94	  }
95	  return null;
96	}
